    TEST_TARGET = { "Targets you", "Visiert an", "Vous cible", "Te selecciona", "Выбрал вас", "选中你" },
    TEST_MIXED = { "Mixed", "Gemischt", "Mélangé", "Mezclado", "Всё вместе", "混合" },
    SEC_RADAR_SHARE = { "Levels and sharing", "Stufen und Teilen", "Niveaux et partage", "Niveles y compartir", "Уровни и обмен", "等级与共享" },
    OPT_RADAR_SEND = { "Report own sightings to group and guild", "Eigene Sichtungen an Gruppe und Gilde melden", "Signaler ses repérages au groupe et à la guilde", "Informar de tus avistamientos al grupo y la hermandad", "Сообщать свои наблюдения группе и гильдии", "向队伍和公会报告自己的发现" },
    OPT_RADAR_LISTEN = { "Use sightings from others", "Sichtungen anderer übernehmen", "Utiliser les repérages des autres", "Usar avistamientos de otros", "Использовать наблюдения других", "采用他人的发现" },
    OPT_RADAR_LISTEN_TIP = { "Users of this addon and of Spy in your group, raid or guild report the enemies they see. Their real levels are kept (also for enemies far above you); enemies reported in your zone join the list, a stealthed one with its warning. Nothing is sent by this.", "Nutzer dieses Addons und von Spy in deiner Gruppe, deinem Schlachtzug oder deiner Gilde melden die Gegner, die sie sehen. Deren echte Stufen werden gemerkt (auch für Gegner weit über dir); in deiner Zone gemeldete Gegner kommen in die Liste, einer in Verstohlenheit mit seiner Warnung. Gesendet wird dadurch nichts.", "Les utilisateurs de cet addon et de Spy de votre groupe, raid ou guilde signalent les ennemis vus. Leurs vrais niveaux sont gardés ; les ennemis signalés dans votre zone rejoignent la liste, un camouflé avec son alerte. Rien n'est envoyé.", "Los usuarios de este addon y de Spy de tu grupo, banda o hermandad informan de los enemigos que ven. Se guardan sus niveles reales; los enemigos de tu zona entran en la lista, uno en sigilo con su aviso. No se envía nada.", "Пользователи этого аддона и Spy в группе, рейде или гильдии сообщают о врагах. Их реальные уровни запоминаются; враги из вашей зоны попадают в список, незаметный — с предупреждением. Ничего не отправляется.", "队伍、团队或公会中本插件和 Spy 的用户会报告所见敌人。会记住其真实等级；你所在区域的敌人会加入列表，潜行敌人附带警告。不会发送任何内容。" },
    WZ_RADARSHARE_TEXT = { "The radar shares with the people you play with: users of this addon and of Spy in your group, raid and guild. You get the real level of enemies far above you and sightings in your zone, a stealthed enemy with its warning; optionally your own sightings go to them. A newer version among them is pointed out once.", "Das Radar teilt mit den Leuten, mit denen du spielst: Nutzer dieses Addons und von Spy in Gruppe, Schlachtzug und Gilde. Du bekommst die echte Stufe von Gegnern weit über dir und Sichtungen in deiner Zone, einen Gegner in Verstohlenheit mit seiner Warnung; auf Wunsch gehen deine Sichtungen an sie. Hat jemand eine neuere Version, wird darauf einmal hingewiesen.", "Le radar partage avec ceux avec qui vous jouez : utilisateurs de cet addon et de Spy du groupe, raid et guilde. Vous recevez le vrai niveau des ennemis bien au-dessus et les repérages de votre zone ; vos repérages peuvent leur être envoyés. Une version plus récente chez eux est signalée une fois.", "El radar comparte con quienes juegas: usuarios de este addon y de Spy en grupo, banda y hermandad. Recibes el nivel real de enemigos muy por encima y avistamientos de tu zona; opcionalmente envías los tuyos. Una versión más nueva entre ellos se indica una vez.", "Радар обменивается с теми, с кем вы играете: пользователями этого аддона и Spy в группе, рейде и гильдии. Вы получаете реальный уровень врагов намного выше и наблюдения в вашей зоне; по желанию отправляются ваши. О более новой версии у них сообщается один раз.", "雷达与一起游戏的人共享：队伍、团队和公会中本插件和 Spy 的用户。你会获得远高于你的敌人的真实等级和本区域的发现；可选发送自己的发现。若有人使用更新版本会提示一次。" },
    RADAR_REPORTED = { "reported by %s", "gemeldet von %s", "signalé par %s", "informado por %s", "сообщил %s", "由 %s 报告" },
    OPT_VERSIONCHECK = { "Point out newer versions", "Auf neuere Versionen hinweisen", "Signaler les nouvelles versions", "Avisar de versiones nuevas", "Сообщать о новых версиях", "提示新版本" },
    OPT_VERSIONCHECK_TIP = { "Your version goes to your group and guild as an invisible addon message; if someone there has a newer one, the chat says so once.", "Deine Version geht als unsichtbare Addon-Nachricht an Gruppe und Gilde; hat dort jemand eine neuere, steht das einmal im Chat.", "Votre version est envoyée au groupe et à la guilde en message d'addon invisible ; si quelqu'un en a une plus récente, le chat l'indique une fois.", "Tu versión va al grupo y la hermandad como mensaje de addon invisible; si alguien tiene una más nueva, el chat lo indica una vez.", "Ваша версия уходит группе и гильдии невидимым сообщением; если у кого-то новее, чат сообщит один раз.", "你的版本以隐藏插件消息发送给队伍和公会；若有人版本更新，聊天框会提示一次。" },
    NEW_VERSION = { "version %s is out (you have %s) – update on CurseForge.", "Version %s ist erschienen (du hast %s) – Update auf CurseForge.", "la version %s est sortie (vous avez %s) – mise à jour sur CurseForge.", "ha salido la versión %s (tienes %s): actualiza en CurseForge.", "вышла версия %s (у вас %s) — обновите на CurseForge.", "版本 %s 已发布（你使用 %s）——请在 CurseForge 更新。" },
    SEC_RADAR_TEST = { "Try it", "Ausprobieren", "Essayer", "Probar", "Попробовать", "试用" },
    OPT_RADAR_SEND_TIP = { "Your sightings go to your group, raid and guild as invisible addon messages for users of this addon, with stealth, targeting and zone. Each enemy at most once a minute (every five minutes for a plain sighting).", "Deine Sichtungen gehen als unsichtbare Addon-Nachrichten an Gruppe, Schlachtzug und Gilde, für Nutzer dieses Addons, mit Verstohlenheit, Anvisieren und Zone. Pro Gegner höchstens einmal pro Minute (bei einfacher Sichtung alle fünf Minuten).", "Vos repérages vont au groupe, raid et guilde en messages d'addon invisibles pour les utilisateurs de cet addon, avec camouflage, ciblage et zone. Au plus une fois par minute par ennemi.", "Tus avistamientos van al grupo, banda y hermandad como mensajes de addon invisibles para usuarios de este addon, con sigilo, selección y zona. Como mucho una vez por minuto por enemigo.", "Ваши наблюдения уходят группе, рейду и гильдии невидимыми сообщениями для пользователей этого аддона, с незаметностью, выбором цели и зоной. Не чаще раза в минуту на врага.", "你的发现以隐藏插件消息发送给队伍、团队和公会中的本插件用户，包含潜行、选中和区域信息。每个敌人最多每分钟一次。" },
    OPT_RADAR_SENDSPY = { "Also in Spy's format", "Zusätzlich im Spy-Format", "Aussi au format Spy", "También en formato Spy", "Также в формате Spy", "同时使用 Spy 格式" },
    OPT_RADAR_SENDSPY_TIP = { "Plain sightings with their level also go out the way Spy sends them, so Spy users in your group and guild get them too.", "Einfache Sichtungen mit Stufe gehen zusätzlich so hinaus, wie Spy sie sendet, damit auch Spy-Nutzer in Gruppe und Gilde sie bekommen.", "Les repérages simples avec niveau partent aussi comme Spy les envoie, pour les utilisateurs de Spy.", "Los avistamientos simples con nivel también se envían como Spy, para los usuarios de Spy.", "Простые наблюдения с уровнем также отправляются как у Spy, для пользователей Spy.", "带等级的普通发现也以 Spy 的方式发送，供 Spy 用户接收。" },
    SEC_TOGETHER = { "Questing together", "Zusammen questen", "Quêtes en groupe", "Misiones en grupo", "Задания вместе", "组队任务" },
    ITEM_together = { "Questing together", "Zusammen questen", "Quêtes en groupe", "Misiones en grupo", "Задания вместе", "组队任务" },
    OPT_TOG_TIP = { "In a group, members using this addon share their quests and progress: quests someone lacks can be shared from the panel element, and a window shows the quests the group is working on.", "In einer Gruppe teilen Mitglieder mit diesem Addon ihre Quests und ihren Fortschritt: Quests, die jemandem fehlen, lassen sich übers Panel-Element teilen, und ein Fenster zeigt die Quests, an denen die Gruppe arbeitet.", "En groupe, les membres utilisant cet addon partagent quêtes et progression : les quêtes manquantes se partagent depuis l'élément du panneau, une fenêtre montre les quêtes en cours du groupe.", "En grupo, los miembros con este addon comparten misiones y progreso: las que le faltan a alguien se comparten desde el elemento del panel, y una ventana muestra las misiones en curso del grupo.", "В группе участники с этим аддоном обмениваются заданиями и прогрессом: недостающие задания можно поделиться через элемент панели, окно показывает задания, над которыми работает группа.", "在队伍中，使用本插件的成员共享任务和进度：可通过面板元素共享他人缺少的任务，窗口显示队伍正在进行的任务。" },
    TOG_TEXT = { "Works with group members who use this addon too. A quest shows in the window once someone holding it makes progress while you are grouped and at least two of you have it; it stays until everyone has finished it, then folds away. The group leader can hide a quest for everyone (cross). Put the element on the panel with a right-click on it: Elements > System.", "Funktioniert mit Gruppenmitgliedern, die dieses Addon ebenfalls nutzen. Eine Quest erscheint im Fenster, sobald jemand, der sie hat, in der Gruppe Fortschritt macht und mindestens zwei von euch sie haben; sie bleibt, bis alle sie fertig haben, dann klappt sie weg. Der Gruppenanführer kann eine Quest für alle ausblenden (Kreuz). Das Element kommt per Rechtsklick aufs Panel dazu: Elemente > System.", "Fonctionne avec les membres utilisant aussi cet addon. Une quête apparaît dès qu'un détenteur progresse en groupe et qu'au moins deux d'entre vous l'ont ; elle reste jusqu'à ce que tous l'aient terminée, puis se replie. Le chef peut la masquer pour tous (croix). Élément : clic droit sur le panneau > Éléments > Système.", "Funciona con miembros que también usan este addon. Una misión aparece cuando alguien que la tiene progresa en grupo y al menos dos la tenéis; queda hasta que todos la terminan y luego se pliega. El líder puede ocultarla para todos (cruz). Elemento: clic derecho en el panel > Elementos > Sistema.", "Работает с участниками, у которых тоже есть этот аддон. Задание появляется, когда кто-то из владельцев продвигается в группе и оно есть хотя бы у двоих; остаётся, пока все не выполнят, затем сворачивается. Лидер может скрыть его для всех (крестик). Элемент: правый клик по панели > Элементы > Система.", "需要队友也使用本插件。当持有任务的人在组队时取得进度且至少两人拥有该任务时，任务出现在窗口中；直到所有人完成才折叠消失。队长可为所有人隐藏任务（叉号）。添加元素：右键面板 > 元素 > 系统。" },
    OPT_TOG_WINDOW = { "Window with the group's quests", "Fenster mit den Gruppenquests", "Fenêtre des quêtes du groupe", "Ventana con las misiones del grupo", "Окно с заданиями группы", "队伍任务窗口" },
    OPT_TOG_WINDOW_TIP = { "Movable (drag it); the lock in its corner fixes it.", "Frei verschiebbar (ziehen); das Schloss in der Ecke fixiert es.", "Déplaçable (glisser) ; le cadenas dans le coin la fixe.", "Movible (arrastrar); el candado de la esquina la fija.", "Перемещается перетаскиванием; замок в углу фиксирует.", "可拖动移动；角落的锁可固定。" },
    OPT_TOG_LOCKED = { "Window locked", "Fenster gesperrt", "Fenêtre verrouillée", "Ventana bloqueada", "Окно закреплено", "窗口已锁定" },
    TOG_LOCK = { "Lock the window", "Fenster sperren", "Verrouiller la fenêtre", "Bloquear la ventana", "Закрепить окно", "锁定窗口" },
    TOG_UNLOCK = { "Unlock the window", "Fenster entsperren", "Déverrouiller la fenêtre", "Desbloquear la ventana", "Открепить окно", "解锁窗口" },
    TOG_HIDE = { "Hide this quest for the whole group", "Diese Quest für die ganze Gruppe ausblenden", "Masquer cette quête pour tout le groupe", "Ocultar esta misión para todo el grupo", "Скрыть задание для всей группы", "为全队隐藏此任务" },
    TOG_NOADDON = { "no addon", "kein Addon", "pas d'addon", "sin addon", "нет аддона", "无插件" },
    TOG_GAVE_IN = { "Turned in:", "Abgegeben:", "Rendue :", "Entregada:", "Сдали:", "已交：" },
    TOG_NOT_YET = { "Not yet:", "Noch nicht:", "Pas encore :", "Aún no:", "Ещё нет:", "尚未：" },
    TOG_GOT_IT = { "Got it", "Verstanden", "Compris", "Entendido", "Понятно", "知道了" },
    TOG_LEADER_CONFIRMS = { "The leader confirms.", "Der Anführer bestätigt.", "Le chef confirme.", "El líder confirma.", "Лидер подтверждает.", "由队长确认。" },
    TOG_TOO_FAR = { "too far away", "zu weit weg", "trop loin", "demasiado lejos", "слишком далеко", "距离太远" },
    TOG_TEST_PARTNER_TURNIN = { "Partner turns in", "Partner gibt ab", "Le partenaire rend", "El compañero entrega", "Партнёр сдаёт", "队友交任务" },
    TOG_TEST_MY_TURNIN = { "Turn in myself", "Selbst abgeben", "Rendre moi-même", "Entregar yo", "Сдать самому", "自己交任务" },
    TOG_TEST_FAR = { "Far / near", "Weit weg / nah", "Loin / près", "Lejos / cerca", "Далеко / рядом", "远 / 近" },
    OPT_TOG_TEST_TURNIN = { "Try out turning in", "Abgabe ausprobieren", "Essayer le rendu", "Probar la entrega", "Попробовать сдачу", "试用交任务" },
    OPT_TOG_TEST_TURNIN_TIP = { "With the test running: the partner turns in a quest you still hold (the reminder comes after 5 seconds instead of 60), you turn one in, the partner walks away or comes back.", "Bei laufendem Test: Der Partner gibt eine Quest ab, die du noch hast (der Hinweis kommt nach 5 statt 60 Sekunden), du gibst eine ab, der Partner entfernt sich oder kommt zurück.", "Pendant le test : le partenaire rend une quête que vous avez encore (le rappel vient après 5 secondes au lieu de 60), vous en rendez une, le partenaire s'éloigne ou revient.", "Con la prueba en marcha: el compañero entrega una misión que aún tienes (el aviso llega a los 5 segundos en vez de 60), tú entregas una, el compañero se aleja o vuelve.", "Во время теста: партнёр сдаёт задание, которое у вас ещё есть (напоминание через 5 секунд вместо 60), вы сдаёте задание, партнёр уходит или возвращается.", "测试进行时：队友交了你还持有的任务（提醒在 5 秒而非 60 秒后出现），你交一个任务，队友走远或回来。" },
    GXP_BAGS = { "Bag slots", "Taschenplätze", "Emplacements de sac", "Huecos de bolsa", "Места в сумках", "背包空位" },
    GXP_BAGS_N = { "%d of %d free", "%d von %d frei", "%d sur %d libres", "%d de %d libres", "%d из %d свободно", "%d / %d 空闲" },
    GXP_AMMO = { "Ammunition", "Munition", "Munitions", "Munición", "Боеприпасы", "弹药" },
    OPT_TOG_SOUNDDONE = { "Sound when all are done", "Ton, wenn alle fertig sind", "Son quand tous ont fini", "Sonido cuando todos terminan", "Звук, когда все выполнили", "全部完成时播放声音" },
    OPT_TOG_SOUNDDONE_TIP = { "A shown quest done by everyone holding it: a sound plays and it glows golden. It stays in the window until all have turned it in.", "Eine angezeigte Quest ist bei allen erfüllt, die sie haben: Ein Ton erklingt und sie leuchtet golden auf. Sie bleibt im Fenster, bis alle sie abgegeben haben.", "Une quête affichée terminée par tous ceux qui l'ont : un son retentit et elle brille en or. Elle reste dans la fenêtre jusqu'à ce que tous l'aient rendue.", "Una misión mostrada completada por todos los que la tienen: suena un sonido y brilla en dorado. Se queda en la ventana hasta que todos la entreguen.", "Показанное задание выполнено всеми, у кого оно есть: звучит сигнал и оно вспыхивает золотом. Оно остаётся в окне, пока все его не сдадут.", "显示的任务被所有持有者完成：播放声音并发出金光。它会留在窗口中，直到所有人都交了任务。" },
    OPT_TOG_TURNIN = { "Remind when not all turned in", "Erinnern, wenn nicht alle abgegeben haben", "Rappeler si tous n'ont pas rendu", "Avisar si no todos entregaron", "Напоминать, если сдали не все", "未全部交任务时提醒" },
    OPT_TOG_TURNIN_TIP = { "Someone turns in a shown quest that others still hold: after 60 seconds a sound plays, the quest pulses red and a note next to the window says who turned it in and who has not. It ends when the group leader confirms it.", "Jemand gibt eine angezeigte Quest ab, die andere noch haben: Nach 60 Sekunden erklingt ein Ton, die Quest pulsiert rot und ein Hinweis neben dem Fenster zeigt, wer sie abgegeben hat und wer noch nicht. Das endet, wenn der Gruppenanführer es bestätigt.", "Quelqu'un rend une quête affichée que d'autres ont encore : après 60 secondes un son retentit, la quête pulse en rouge et une note à côté de la fenêtre indique qui l'a rendue et qui non. Cela cesse quand le chef du groupe le confirme.", "Alguien entrega una misión mostrada que otros aún tienen: a los 60 segundos suena un sonido, la misión pulsa en rojo y una nota junto a la ventana indica quién la entregó y quién no. Termina cuando el líder del grupo lo confirma.", "Кто-то сдаёт показанное задание, которое у других ещё есть: через 60 секунд звучит сигнал, задание пульсирует красным, а заметка рядом с окном показывает, кто сдал и кто нет. Это прекращается, когда лидер группы подтвердит.", "有人交了其他人仍持有的显示任务：60 秒后播放声音，任务闪烁红色，窗口旁的提示显示谁已交、谁未交。队长确认后结束。" },
    WZ_NEWMARKS = { "New in the options", "Neu in den Optionen", "Nouveau dans les options", "Novedades en las opciones", "Новое в настройках", "设置中的新内容" },
    WZ_NEWMARKS_TEXT = { "What a version brings is marked in the options with the game's glowing turquoise diamond: behind a new setting, on its tab and on its page in the list on the left. A feature that is new as a whole is marked in the list only.", "Was eine Version neu bringt, ist in den Optionen mit dem leuchtend türkisen Diamanten des Spiels markiert: hinter einer neuen Einstellung, an ihrem Reiter und an ihrer Seite in der Liste links. Eine ganz neue Funktion ist nur in der Liste markiert.", "Ce qu'apporte une version est marqué dans les options par le diamant turquoise lumineux du jeu : derrière un nouveau réglage, sur son onglet et sur sa page dans la liste à gauche. Une fonction entièrement nouvelle n'est marquée que dans la liste.", "Lo que trae una versión se marca en las opciones con el diamante turquesa brillante del juego: tras un ajuste nuevo, en su pestaña y en su página de la lista de la izquierda. Una función totalmente nueva solo se marca en la lista.", "Новое в версии отмечено в настройках светящимся бирюзовым ромбом игры: за новой настройкой, на её вкладке и на её странице в списке слева. Полностью новая функция отмечена только в списке.", "新版本带来的内容在设置中以游戏的发光青色菱形标记：在新设置后、其标签页上以及左侧列表中的页面上。全新的功能只在列表中标记。" },
    TOG_ANN_MINE_A = { "I have completed the quest %s!", "Ich habe die Quest %s abgeschlossen!", "J'ai terminé la quête %s !", "¡He completado la misión %s!", "Выполнено задание %s!", "我完成了任务%s！" },
    TOG_ANN_MINE_B = { "Quest %s is done!", "Quest %s ist erledigt!", "Quête %s accomplie !", "¡Misión %s hecha!", "Задание %s готово!", "任务%s已完成！" },
    TOG_ANN_MINE_C = { "Done with %s!", "Fertig mit %s!", "Fini avec %s !", "¡Listo con %s!", "С заданием %s покончено!", "%s搞定了！" },
    TOG_ANN_GROUP_A = { "We as a group (%s) have completed the quest %s! Good work!", "Wir haben als Gruppe (%s) die Quest %s abgeschlossen! Gute Arbeit!", "En groupe (%s), nous avons terminé la quête %s ! Beau travail !", "¡Como grupo (%s) hemos completado la misión %s! ¡Buen trabajo!", "Группой (%s) мы выполнили задание %s! Отличная работа!", "我们小队（%s）完成了任务%s！干得好！" },
    TOG_ANN_GROUP_B = { "Done together: %s completed the quest %s. Great team!", "Gemeinsam geschafft: %s haben die Quest %s abgeschlossen. Starkes Team!", "Réussi ensemble : %s ont terminé la quête %s. Belle équipe !", "Logrado juntos: %s completaron la misión %s. ¡Gran equipo!", "Вместе справились: %s выполнили задание %s. Отличная команда!", "齐心协力：%s完成了任务%s。好团队！" },
    TOG_ANN_GROUP_C = { "Teamwork! %s finished the quest %s. Keep it up!", "Teamwork! %s haben die Quest %s erledigt. Weiter so!", "Travail d'équipe ! %s ont fini la quête %s. Continuez !", "¡Trabajo en equipo! %s terminaron la misión %s. ¡Seguid así!", "Командная работа! %s завершили задание %s. Так держать!", "团队合作！%s完成了任务%s。继续加油！" },
    TOG_ANN_GROUP_D = { "Quest done by all: %s completed %s. Well played!", "Quest von allen erledigt: %s haben %s abgeschlossen. Gut gemacht!", "Quête finie par tous : %s ont terminé %s. Bien joué !", "Misión hecha por todos: %s completaron %s. ¡Bien jugado!", "Задание выполнено всеми: %s завершили %s. Хорошо сыграно!", "全员完成任务：%s完成了%s。打得好！" },
    TOG_ANN_PICK_A = { "We as a group (%s) are starting the quest %s.", "Wir starten als Gruppe (%s) die Quest %s.", "En groupe (%s), nous commençons la quête %s.", "Como grupo (%s) empezamos la misión %s.", "Группой (%s) мы начинаем задание %s.", "我们小队（%s）开始任务%s。" },
    TOG_ANN_PICK_B = { "Next up for the group (%s): the quest %s. Let's go!", "Als Nächstes für die Gruppe (%s): die Quest %s. Los geht's!", "Prochaine étape pour le groupe (%s) : la quête %s. C'est parti !", "Lo siguiente para el grupo (%s): la misión %s. ¡Vamos!", "Следующее для группы (%s): задание %s. Вперёд!", "小队（%s）的下一个目标：任务%s。出发！" },
    TOG_ANN_HIDE_A = { "I have hidden the quest %s for the group (%s). We'll do it later!", "Ich habe die Quest %s für die Gruppe (%s) verborgen. Erledigen wir später!", "J'ai masqué la quête %s pour le groupe (%s). On la fera plus tard !", "He ocultado la misión %s para el grupo (%s). ¡La haremos más tarde!", "Я скрыл(а) задание %s для группы (%s). Сделаем позже!", "我隐藏了任务%s（小队：%s）。稍后再做！" },
    TOG_ANN_HIDE_B = { "The quest %s is set aside for the group (%s) – later!", "Die Quest %s ist für die Gruppe (%s) zurückgestellt – später!", "La quête %s est mise de côté pour le groupe (%s) – plus tard !", "La misión %s queda aparcada para el grupo (%s), ¡más tarde!", "Задание %s отложено для группы (%s) – позже!", "任务%s已为小队（%s）暂缓——稍后再做！" },
    OPT_TOG_ANNPICK = { "As leader: say when I pick a quest for the group", "Als Anführer: melden, wenn ich eine Quest für die Gruppe auswähle", "En tant que chef : annoncer quand je choisis une quête pour le groupe", "Como líder: avisar cuando elijo una misión para el grupo", "Как лидер: сообщать, когда я выбираю задание для группы", "作为队长：为队伍选择任务时通报" },
    OPT_TOG_ANNPICK_TIP = { "Showing a quest for the group (the \"+\" in the window) says so in the group chat, with the names of the members using the addon and a link to the quest.", "Zeigst du eine Quest für die Gruppe an (das „+“ im Fenster), steht das im Gruppenchat, mit den Namen der Addon-Nutzer und Link zur Quest.", "Afficher une quête pour le groupe (le « + » de la fenêtre) l'annonce dans le canal de groupe, avec les noms des utilisateurs de l'addon et un lien vers la quête.", "Mostrar una misión para el grupo (el «+» de la ventana) lo anuncia en el chat de grupo, con los nombres de quienes usan el addon y un enlace a la misión.", "Показ задания группе («+» в окне) сообщается в чат группы с именами пользователей аддона и ссылкой на задание.", "为队伍显示任务（窗口中的“+”）时会在队伍频道通报，附上插件用户的名字和任务链接。" },
    OPT_TOG_ANNHIDE = { "As leader: say when I hide a quest for the group", "Als Anführer: melden, wenn ich eine Quest für die Gruppe verberge", "En tant que chef : annoncer quand je masque une quête pour le groupe", "Como líder: avisar cuando oculto una misión para el grupo", "Как лидер: сообщать, когда я скрываю задание для группы", "作为队长：为队伍隐藏任务时通报" },
    OPT_TOG_ANNHIDE_TIP = { "Hiding a quest for everyone (the cross on the quest) says so in the group chat: set aside, done later.", "Verbirgst du eine Quest für alle (das Kreuz an der Quest), steht das im Gruppenchat: zurückgestellt, später erledigt.", "Masquer une quête pour tous (la croix sur la quête) l'annonce dans le canal de groupe : mise de côté, à faire plus tard.", "Ocultar una misión para todos (la cruz en la misión) lo anuncia en el chat de grupo: aparcada, para más tarde.", "Скрытие задания для всех (крестик на задании) сообщается в чат группы: отложено, сделаем позже.", "为所有人隐藏任务（任务上的叉号）时会在队伍频道通报：暂缓，稍后再做。" },
    TOG_ANN_PREVIEW = { "preview, not sent", "Vorschau, nicht gesendet", "aperçu, non envoyé", "vista previa, no enviado", "предпросмотр, не отправлено", "预览，未发送" },
    OPT_TOG_ANNMINE = { "Say in the group chat when I complete a quest", "Im Gruppenchat melden, wenn ich eine Quest abschließe", "Annoncer dans le groupe quand je termine une quête", "Avisar en el chat de grupo al completar una misión", "Сообщать в чат группы, когда я выполняю задание", "完成任务时在队伍频道通报" },
    OPT_TOG_ANNMINE_TIP = { "In a group, a message with a link to the quest goes to the group chat once all its objectives are done – so members without the addon know too.", "In einer Gruppe geht eine Nachricht mit Link zur Quest in den Gruppenchat, sobald alle Ziele erfüllt sind – so wissen es auch Mitglieder ohne das Addon.", "En groupe, un message avec un lien vers la quête part dans le canal de groupe dès que tous ses objectifs sont remplis – pour que les membres sans l'addon le sachent aussi.", "En grupo, un mensaje con un enlace a la misión va al chat de grupo en cuanto se cumplen todos sus objetivos, para que lo sepan también quienes no tienen el addon.", "В группе в чат уходит сообщение со ссылкой на задание, как только выполнены все его цели, – чтобы знали и участники без аддона.", "在队伍中，任务所有目标完成后，会向队伍频道发送带任务链接的消息——让没有插件的队友也知道。" },
    OPT_TOG_ANNGROUP = { "As leader: say when the group has completed a quest", "Als Anführer: melden, wenn die Gruppe eine Quest abgeschlossen hat", "En tant que chef : annoncer quand le groupe a terminé une quête", "Como líder: avisar cuando el grupo complete una misión", "Как лидер: сообщать, когда группа выполнила задание", "作为队长：队伍完成任务时通报" },
    OPT_TOG_ANNGROUP_TIP = { "When everyone using this addon who holds a quest has completed it (you and at least one more), the group leader says so in the group chat, with their names.", "Haben alle, die dieses Addon nutzen und die Quest haben, sie abgeschlossen (du und mindestens ein weiterer), meldet der Gruppenanführer das im Gruppenchat, mit ihren Namen.", "Quand tous ceux qui utilisent cet addon et ont la quête l'ont terminée (vous et au moins un autre), le chef du groupe l'annonce dans le canal de groupe, avec leurs noms.", "Cuando todos los que usan este addon y tienen la misión la han completado (tú y al menos otro), el líder del grupo lo anuncia en el chat de grupo, con sus nombres.", "Когда все, у кого есть аддон и это задание, выполнили его (вы и хотя бы ещё один), лидер группы сообщает об этом в чат группы с их именами.", "当所有使用本插件并持有该任务的成员都完成后（你和至少一名其他成员），队长会在队伍频道通报，并附上他们的名字。" },
    WZ_TOGCHAT = { "Completed quests in the group chat", "Fertige Quests im Gruppenchat", "Quêtes terminées dans le groupe", "Misiones completadas en el chat de grupo", "Выполненные задания в чате группы", "队伍频道中的完成任务" },
    WZ_TOGCHAT_TEXT = { "In a group, the addon says in the group chat when you complete a quest, with a link to it. As group leader it also says when everyone using the addon has completed a quest, when you pick a quest for the group and when you hide one. Members without the addon know at once – each message can be switched off.", "In einer Gruppe meldet das Addon im Gruppenchat, wenn du eine Quest abschließt, mit Link zur Quest. Als Gruppenanführer meldet es außerdem, wenn alle Addon-Nutzer eine Quest abgeschlossen haben, wenn du eine Quest für die Gruppe auswählst und wenn du eine verbirgst. So wissen es auch Mitglieder ohne das Addon – jede Meldung lässt sich abschalten.", "En groupe, l'addon annonce dans le canal de groupe quand vous terminez une quête, avec un lien. En tant que chef, il annonce aussi quand tous les utilisateurs de l'addon ont terminé une quête, quand vous choisissez une quête pour le groupe et quand vous en masquez une. Les membres sans l'addon le savent aussitôt – chaque message peut être désactivé.", "En grupo, el addon avisa en el chat de grupo cuando completas una misión, con un enlace. Como líder también avisa cuando todos los que usan el addon han completado una misión, cuando eliges una misión para el grupo y cuando ocultas una. Así lo saben también quienes no lo tienen; cada aviso se puede desactivar.", "В группе аддон сообщает в чат, когда вы выполняете задание, со ссылкой на него. Как лидер – ещё и когда все пользователи аддона выполнили задание, когда вы выбираете задание для группы и когда скрываете его. Так узнают и участники без аддона; каждое сообщение можно отключить.", "在队伍中，你完成任务时插件会在队伍频道通报，并附上任务链接。作为队长，当所有插件用户完成任务、你为队伍选择任务或隐藏任务时也会通报。没有插件的队友也能马上知道——每条通报都可以关闭。" },
    TOG_SEC_CHAT = { "Chat", "Chat", "Discussion", "Chat", "Чат", "聊天" },
    TOG_SEC_WINDOW = { "Window", "Fenster", "Fenêtre", "Ventana", "Окно", "窗口" },
    TOG_SEC_SHARE = { "Sharing", "Teilen", "Partage", "Compartir", "Передача", "共享" },
    TOG_SEC_TURNIN = { "Done & turned in", "Fertig & abgegeben", "Fini & rendu", "Terminada y entregada", "Выполнено и сдано", "完成与交任务" },
    OPT_TOG_SOUNDTURNIN = { "Sound when not all turned in", "Ton, wenn nicht alle abgegeben haben", "Son si tous n'ont pas rendu", "Sonido si no todos entregaron", "Звук, если сдали не все", "未全部交任务时播放声音" },
    OPT_TOG_SOUNDTURNIN_TIP = { "The reminder after a turn-in plays a sound. Without it the quest still pulses red and the note still shows.", "Die Erinnerung nach einer Abgabe spielt einen Ton. Ohne ihn pulsiert die Quest trotzdem rot und der Hinweis erscheint weiterhin.", "Le rappel après un rendu joue un son. Sans lui, la quête pulse toujours en rouge et la note s'affiche quand même.", "El aviso tras una entrega reproduce un sonido. Sin él, la misión sigue pulsando en rojo y la nota sigue apareciendo.", "Напоминание после сдачи проигрывает звук. Без него задание всё равно пульсирует красным и заметка появляется.", "交任务后的提醒会播放声音。关闭后任务仍会闪烁红色，提示仍会显示。" },
    TOG_OPEN_QUEST = { "Click: open in the quest log", "Klicken: im Questlog öffnen", "Clic : ouvrir dans le journal de quêtes", "Clic: abrir en el registro de misiones", "Щелчок: открыть в журнале заданий", "点击：在任务日志中打开" },
    TOG_NOT_IN_LOG = { "This quest is not in your quest log.", "Diese Quest ist nicht in deinem Questlog.", "Cette quête n'est pas dans votre journal.", "Esta misión no está en tu registro.", "Этого задания нет в вашем журнале.", "此任务不在你的任务日志中。" },
    TOG_TEST_ZONE = { "Test valley", "Testtal", "Vallée de test", "Valle de prueba", "Тестовая долина", "测试山谷" },
    TOG_OTHER_ZONE = { "Other", "Sonstige", "Autres", "Otras", "Прочие", "其他" },
    TOG_TURNEDIN = { "turned in", "abgegeben", "rendue", "entregada", "сдано", "已交" },
    TOG_LACKS = { "lacks it", "fehlt", "ne l'a pas", "no la tiene", "нет", "未接" },
