    TOG_WITHOUT = { "Without the addon: %s", "Ohne Addon: %s", "Sans l'addon : %s", "Sin el addon: %s", "Без аддона: %s", "未安装插件：%s" },
    TOG_NOGROUP = { "No group", "Keine Gruppe", "Pas de groupe", "Sin grupo", "Нет группы", "未组队" },
    TOG_SHARE_N = { "%d to share", "%d zu teilen", "%d à partager", "%d por compartir", "Поделиться: %d", "%d 个可共享" },
    TOG_ACTIVE_N = { "%d active", "%d aktiv", "%d actives", "%d activas", "Активных: %d", "%d 个进行中" },
    TOG_SAME = { "All have the same", "Alle gleich", "Tous pareil", "Todos igual", "У всех одинаково", "任务一致" },
    TOG_SHARE = { "Share: %s", "Teilen: %s", "Partager : %s", "Compartir: %s", "Поделиться: %s", "共享：%s" },
    TOG_NOTSHAREABLE = { "(cannot be shared)", "(nicht teilbar)", "(non partageable)", "(no se puede compartir)", "(нельзя поделиться)", "（不可共享）" },
    CLICK_TOGETHER = { "Click: share quests others lack", "Klick: fehlende Quests teilen", "Clic : partager les quêtes manquantes", "Clic: compartir misiones que faltan", "Клик: поделиться недостающими", "点击：共享他人缺少的任务" },
    WZ_TOGETHER_ITEM = { "Element on the panel", "Element im Panel", "Élément sur le panneau", "Elemento en el panel", "Элемент на панели", "面板元素" },
    WZ_TOGETHER_TEXT = { "In a group, members using this addon share their quests and progress. A window lists the quests the group is working on, with everyone's progress, titles in the colour of their difficulty (a click opens the quest); members too far away for the kill are dimmed. Quests someone lacks are shared from the button at the top, sorted by zone. A quest stays until all have turned it in. Above it: everyone's XP, free bag slots and, for hunters, their ammunition.", "In einer Gruppe teilen Mitglieder mit diesem Addon ihre Quests und ihren Fortschritt. Ein Fenster listet die Quests, an denen die Gruppe arbeitet, mit dem Fortschritt aller, die Titel in der Farbe ihrer Schwierigkeit (ein Klick öffnet die Quest); wer für den Kill zu weit weg ist, wird blass. Fehlende Quests teilst du über den Knopf oben, sortiert nach Gebiet. Eine Quest bleibt, bis alle sie abgegeben haben. Darüber: die XP aller, freie Taschenplätze und bei Jägern die Munition.", "En groupe, les membres utilisant cet addon partagent quêtes et progression. Une fenêtre liste les quêtes en cours avec la progression de chacun, titres colorés selon leur difficulté (un clic ouvre la quête) ; les membres trop loin pour le kill sont estompés. Les quêtes manquantes se partagent via le bouton en haut, triées par zone. Une quête reste jusqu'à ce que tous l'aient rendue. Au-dessus : l'XP de chacun, les emplacements de sac libres et, pour les chasseurs, les munitions.", "En grupo, los miembros con este addon comparten misiones y progreso. Una ventana lista las misiones en curso con el progreso de todos, títulos en el color de su dificultad (un clic abre la misión); quien está demasiado lejos para la muerte aparece atenuado. Las misiones que faltan se comparten con el botón de arriba, ordenadas por zona. Una misión se queda hasta que todos la entreguen. Encima: la XP de todos, huecos de bolsa libres y, para cazadores, la munición.", "В группе участники с этим аддоном обмениваются заданиями и прогрессом. Окно перечисляет задания группы с прогрессом каждого, названия окрашены по сложности (щелчок открывает задание); кто слишком далеко для убийства, показан бледно. Недостающими заданиями делятся кнопкой сверху, по зонам. Задание остаётся, пока все его не сдадут. Выше: опыт всех, свободные места в сумках и боеприпасы охотников.", "在队伍中，使用本插件的成员共享任务和进度。窗口列出队伍进行中的任务及每人进度，标题按难度着色（点击打开任务）；距离太远无法获得击杀的成员会变淡。缺少的任务可通过顶部按钮按区域共享。任务会保留到所有人都交了为止。上方显示每人的经验、背包空位以及猎人的弹药。" },
    TOG_MISSING_N = { "%d missing", "%d fehlt", "%d manquante(s)", "%d falta(n)", "Не хватает: %d", "缺少 %d 个" },
    TOG_PICK = { "Show for the group", "Für die Gruppe anzeigen", "Afficher pour le groupe", "Mostrar para el grupo", "Показать группе", "为队伍显示" },
    TOG_PICK_TIP = { "Pick a quest for the group (leader)", "Quest für die Gruppe auswählen (Anführer)", "Choisir une quête pour le groupe (chef)", "Elegir una misión para el grupo (líder)", "Выбрать задание для группы (лидер)", "为队伍选择任务（队长）" },
    TOG_PICK_NONE = { "No other quests", "Keine weiteren Quests", "Aucune autre quête", "No hay más misiones", "Других заданий нет", "没有其他任务" },
    TOG_MISSING_HEAD = { "Missing in the group", "Fehlt in der Gruppe", "Manque dans le groupe", "Falta en el grupo", "Не хватает в группе", "队伍中缺少" },
    TOG_SHARE_BTN = { "Share", "Teilen", "Partager", "Compartir", "Поделиться", "共享" },
    TOG_TEST_QUEST = { "Test quest %d", "Testquest %d", "Quête test %d", "Misión de prueba %d", "Тестовое задание %d", "测试任务 %d" },
    TOG_TEST_START = { "Start", "Starten", "Démarrer", "Iniciar", "Старт", "开始" },
    TOG_TEST_STOP = { "Stop", "Beenden", "Arrêter", "Terminar", "Стоп", "结束" },
    TOG_TEST_ADD = { "New quest", "Neue Quest", "Nouvelle quête", "Nueva misión", "Новое задание", "新任务" },
    TOG_TEST_UPDATE = { "Update", "Aktualisieren", "Mettre à jour", "Actualizar", "Обновить", "更新" },
    TOG_TEST_FINISH = { "Finish", "Fertigstellen", "Terminer", "Completar", "Завершить", "完成" },
    OPT_TOG_TEST_TIP = { "Step by step with a made-up partner (nothing is sent, your real quests stay hidden meanwhile): add a quest, update one (a row flashes), finish one (it pulses, then folds away). Every third new quest is missing for the partner.", "Schritt für Schritt mit einem erfundenen Mitspieler (gesendet wird nichts, deine echten Quests sind solange ausgeblendet): Quest hinzufügen, eine aktualisieren (eine Zeile leuchtet), eine fertigstellen (sie pulsiert und klappt dann weg). Jede dritte neue Quest fehlt dem Mitspieler.", "Pas à pas avec un partenaire fictif (rien n'est envoyé) : ajouter une quête, en mettre une à jour, en terminer une. Une nouvelle quête sur trois manque au partenaire.", "Paso a paso con un compañero inventado (no se envía nada): añadir una misión, actualizar una, completar una. Una de cada tres nuevas le falta al compañero.", "Пошагово с вымышленным напарником (ничего не отправляется): добавить задание, обновить, завершить. Каждого третьего нового задания у напарника нет.", "与虚构队友逐步测试（不会发送任何内容）：添加任务、更新任务、完成任务。每第三个新任务队友缺少。" },
    TOG_GRIP = { "Drag: width and the highest the window may get (it scrolls beyond)", "Ziehen: Breite und maximale Höhe des Fensters (darüber hinaus scrollt es)", "Glisser : largeur et hauteur maximale (au-delà, défilement)", "Arrastrar: ancho y altura máxima (más allá se desplaza)", "Тянуть: ширина и максимальная высота (дальше прокрутка)", "拖动：宽度和最大高度（超出后滚动）" },
    SEC_GROUPXP = { "Group XP", "EP der Gruppe", "XP du groupe", "PE del grupo", "Опыт группы", "队伍经验" },
    OPT_TOG_XPLOCKED = { "XP window locked", "EP-Fenster gesperrt", "Fenêtre d'XP verrouillée", "Ventana de PE bloqueada", "Окно опыта закреплено", "经验窗口已锁定" },
    OPT_TOG_XPWIN = { "Show the members' XP", "EP der Mitspieler anzeigen", "Afficher l'XP des membres", "Mostrar la PE de los miembros", "Показывать опыт участников", "显示队友经验" },
    OPT_TOG_XPWIN_TIP = { "Level and XP of every member using this addon, with a bar in the XP bar's look, at the top of the quest window.", "Stufe und EP aller Mitspieler mit diesem Addon, mit einer Leiste im Look der EP-Leiste, ganz oben im Questfenster.", "Niveau et XP de chaque membre utilisant cet addon, avec une barre au style de la barre d'XP, en haut de la fenêtre des quêtes.", "Nivel y PE de cada miembro con este addon, con una barra del estilo de la barra de PE, arriba en la ventana de misiones.", "Уровень и опыт каждого участника с этим аддоном, с полосой в стиле полосы опыта, вверху окна заданий.", "在任务窗口顶部以经验条样式显示每位使用本插件队友的等级和经验。" },
    OPT_TOG_XPSEP = { "In a window of its own", "In einem eigenen Fenster", "Dans une fenêtre à part", "En una ventana propia", "В отдельном окне", "独立窗口" },
    OPT_TOG_XPSEP_TIP = { "Instead of the top of the quest window: a window of its own in the same look, hanging below the quest window until you drag it away.", "Statt oben im Questfenster: ein eigenes Fenster in gleicher Optik, das unter dem Questfenster hängt, bis du es wegziehst.", "Au lieu du haut de la fenêtre des quêtes : une fenêtre à part de même style, accrochée dessous jusqu'à ce que vous la déplaciez.", "En lugar de arriba en la ventana de misiones: una ventana propia con el mismo aspecto, colgada debajo hasta que la muevas.", "Вместо верха окна заданий: отдельное окно того же вида, висит под окном заданий, пока вы его не перетащите.", "不在任务窗口顶部，而是同样外观的独立窗口，默认附在任务窗口下方，可拖走。" },
    TOG_NONE = { "No quest is being followed yet.", "Noch wird keine Quest verfolgt.", "Aucune quête n'est encore suivie.", "Aún no se sigue ninguna misión.", "Пока ни одно задание не отслеживается.", "尚未追踪任何任务。" },
    TOG_NONE_LEADER = { "No quest is being followed yet – pick one with +.", "Noch wird keine Quest verfolgt – wähle eine mit + aus.", "Aucune quête suivie – choisissez-en une avec +.", "Aún no se sigue ninguna misión: elige una con +.", "Пока ничего не отслеживается — выберите задание через +.", "尚未追踪任务——用 + 选择一个。" },
    GXP_QUESTS = { "Finished quests", "Fertige Quests", "Quêtes terminées", "Misiones terminadas", "Выполненные задания", "已完成任务" },
    OPT_TOG_ACCEPT = { "Accept quests shared through the addon", "Über das Addon geteilte Quests annehmen", "Accepter les quêtes partagées via l'addon", "Aceptar misiones compartidas con el addon", "Принимать задания, переданные через аддон", "自动接受通过插件共享的任务" },
    OPT_TOG_ACCEPT_TIP = { "A quest a group member shares with you through this addon is accepted at once. If the game refuses it (a quest before it is missing, wrong level), the one sharing sees it as not shareable for you; a quest you already have is no longer offered.", "Eine Quest, die dir ein Gruppenmitglied über dieses Addon teilt, wird sofort angenommen. Lehnt das Spiel sie ab (eine Vorquest fehlt, falsche Stufe), sieht der Teilende sie für dich als nicht teilbar; eine Quest, die du schon hast, wird nicht mehr angeboten.", "Une quête qu'un membre du groupe vous partage via cet addon est acceptée aussitôt. Si le jeu la refuse (quête précédente manquante, mauvais niveau), celui qui partage la voit comme non partageable pour vous ; une quête que vous avez déjà n'est plus proposée.", "Una misión que un miembro del grupo te comparte con este addon se acepta al instante. Si el juego la rechaza (falta una misión previa, nivel incorrecto), quien comparte la ve como no compartible para ti; una misión que ya tienes deja de ofrecerse.", "Задание, которым участник группы делится с вами через аддон, принимается сразу. Если игра отказывает (нет предыдущего задания, не тот уровень), делящийся видит его как недоступное для вас; задание, которое у вас уже есть, больше не предлагается.", "队友通过本插件共享给你的任务会立即接受。若游戏拒绝（缺少前置任务、等级不符），共享者会看到该任务对你不可共享；你已有的任务不再提供共享。" },
    OPT_TOG_TRACKER = { "Fold up Blizzard's quest tracker", "Blizzards Questanzeige einklappen", "Replier le suivi des quêtes de Blizzard", "Plegar el seguimiento de misiones de Blizzard", "Сворачивать трекер заданий Blizzard", "折叠暴雪任务追踪" },
    OPT_TOG_TRACKER_TIP = { "In a group where most members use this addon (you included), the game's quest tracker folds up, as our window shows the group's quests. It unfolds again afterwards, unless you folded it yourself.", "In einer Gruppe, in der die Mehrheit dieses Addon nutzt (du eingeschlossen), klappt die Questanzeige des Spiels ein, da unser Fenster die Gruppenquests zeigt. Danach klappt sie wieder auf, außer du hattest sie selbst eingeklappt.", "Dans un groupe où la majorité utilise cet addon (vous compris), le suivi des quêtes du jeu se replie, notre fenêtre montrant les quêtes du groupe. Il se déplie ensuite, sauf si vous l'aviez replié vous-même.", "En un grupo donde la mayoría usa este addon (tú incluido), el seguimiento de misiones del juego se pliega, ya que nuestra ventana muestra las del grupo. Después se despliega, salvo que lo hubieras plegado tú.", "В группе, где большинство пользуется этим аддоном (включая вас), трекер заданий игры сворачивается — наше окно показывает задания группы. Потом разворачивается, если вы не сворачивали его сами.", "在大多数成员（包括你）使用本插件的队伍中，游戏任务追踪会折叠，由我们的窗口显示队伍任务。之后会重新展开，除非你自己折叠了它。" },
