    PLACE_FREE = { "Free (move mode)", "Frei (Verschieben-Modus)", "Libre (mode déplacement)", "Libre (modo mover)", "Свободно (режим перемещения)", "自由（移动模式）" },
    OPT_XP_PLACE = { "Where", "Wo", "Où", "Dónde", "Где", "位置" },
    OPT_XP_PLACE_TIP = { "Free: the XP bar (with the reputation bar attached or below) leaves the panel and goes where you place it in move mode. Around the minimap: a ring around a round minimap; the reputation bar then takes the XP bar's place on the panel.", "Frei: Die EP-Leiste (samt angehängter oder darunter liegender Ruf-Leiste) löst sich vom Panel und steht, wo du sie im Verschieben-Modus hinlegst. Um die Minimap: ein Ring um die runde Minimap; die Ruf-Leiste nimmt dann den Platz der EP-Leiste am Panel ein.", "Libre : la barre d'XP (avec la barre de réputation) quitte le panneau et se place où vous la mettez en mode déplacement. Autour de la minicarte : un anneau autour de la minicarte ronde ; la barre de réputation prend alors la place de la barre d'XP sur le panneau.", "Libre: la barra de PE (con la de reputación) deja el panel y va donde la coloques en el modo mover. Alrededor del minimapa: un anillo alrededor del minimapa redondo; la barra de reputación ocupa entonces el lugar de la de experiencia en el panel.", "Свободно: полоса опыта (с полосой репутации) отделяется от панели и ставится в режиме перемещения. Вокруг миникарты: кольцо вокруг круглой миникарты; полоса репутации тогда занимает место полосы опыта на панели.", "自由：经验条（连同声望条）脱离面板，在移动模式中随意摆放。 小地图周围：围绕圆形小地图的圆环；声望条随后在面板上取代经验条的位置。" },
    OPT_POS_RESET = { "Position", "Position", "Position", "Posición", "Положение", "位置" },
    SEC_MOVE = { "Moving", "Verschieben", "Déplacement", "Mover", "Перемещение", "移动" },
    OPT_MOVE = { "Move mode", "Verschieben-Modus", "Mode déplacement", "Modo mover", "Режим перемещения", "移动模式" },
    OPT_MOVE_TIP = { "Place the bars set free, the warnings and the loot text: drag the blue boxes, right-click or Esc finishes.", "Frei platzierte Leisten, Warnungen und Beutetext platzieren: blaue Kästen ziehen, Rechtsklick oder Esc beendet.", "Placez les barres libres, les alertes et le texte de butin : faites glisser les cadres bleus, clic droit ou Échap pour finir.", "Coloca las barras libres, los avisos y el texto de botín: arrastra los recuadros azules; clic derecho o Esc termina.", "Размещайте свободные полосы, предупреждения и текст добычи: тяните синие рамки, ПКМ или Esc — готово.", "摆放自由的条、提醒和拾取文字：拖动蓝框，右键或 Esc 结束。" },
    OPT_SNAP_TIP = { "Dropped frames line up with the grid: their nearest edge or their centre lands on a line.", "Abgelegte Elemente richten sich am Raster aus: Ihre nächste Kante oder ihre Mitte landet auf einer Linie.", "Les éléments déposés s'alignent sur la grille : leur bord le plus proche ou leur centre tombe sur une ligne.", "Los elementos soltados se alinean con la cuadrícula: su borde más cercano o su centro cae en una línea.", "Отпущенные элементы выравниваются по сетке: ближайший край или центр ложится на линию.", "放下的元素对齐网格：最近的边或中心落在线上。" },
