    OPT_PETBAR_TIP = { "Your hunter pet's level and XP as a bar, with the share of the level in the tooltip.", "Stufe und EP deines Jäger-Begleiters als Leiste, mit dem Anteil an der Stufe im Tooltip.", "Niveau et XP de votre familier de chasseur en barre, avec la part du niveau dans l'infobulle.", "Nivel y PE de tu mascota de cazador como barra, con el porcentaje del nivel en la descripción.", "Уровень и опыт питомца охотника в виде полосы, с долей уровня в подсказке.", "以条形显示猎人宠物的等级和经验，提示中显示本级进度。" },
    OPT_PET_PLACE = { "Where", "Wo", "Où", "Dónde", "Где", "位置" },
    OPT_PET_PLACE_TIP = { "Beside the XP bar: both share the XP bar's width. Beside or hanging from the XP bar, the reputation bar cannot hang from it (it goes below). Around the minimap: not with the XP bar there. Without the XP bar in the panel, beside and hanging become free.", "Neben der EP-Leiste: beide teilen sich die Breite der EP-Leiste. Neben oder an der EP-Leiste hängend kann die Ruf-Leiste nicht an ihr hängen (sie rückt darunter). Um die Minimap: nicht zusammen mit der EP-Leiste dort. Ohne EP-Leiste im Panel werden Neben und Hängend zu Frei.", "À côté de la barre d'XP : les deux partagent sa largeur. À côté ou suspendue, la barre de réputation ne peut pas y être suspendue (elle passe en dessous). Autour de la minicarte : pas avec la barre d'XP. Sans barre d'XP sur le panneau, à côté et suspendue deviennent libres.", "Junto a la barra de PE: ambas comparten su ancho. Junto o colgando, la de reputación no puede colgar de ella (va debajo). Alrededor del minimapa: no junto con la barra de PE allí. Sin barra de PE en el panel, junto y colgando pasan a libre.", "Рядом с полосой опыта: обе делят её ширину. Рядом или подвешенной — полоса репутации не может висеть на полосе опыта (уходит ниже). Вокруг миникарты: не вместе с полосой опыта там. Без полосы опыта на панели «рядом» и «подвешенной» становятся свободными.", "经验条旁：两者共享经验条宽度。在经验条旁或悬挂时，声望条不能悬挂在经验条上（移到下方）。小地图周围：不能与经验条同时在那里。面板上没有经验条时，旁边和悬挂变为自由。" },
    PET_SIDE = { "Beside the XP bar", "Neben der EP-Leiste", "À côté de la barre d'XP", "Junto a la barra de PE", "Рядом с полосой опыта", "经验条旁" },
    PET_ATTACH = { "Hanging from the XP bar", "An der EP-Leiste hängend", "Suspendue à la barre d'XP", "Colgando de la barra de PE", "Под полосой опыта", "悬挂在经验条下" },
