    OPT_LO_THRESHOLD_TIP = { "The window only appears for gear at least this much better.", "Das Fenster erscheint nur für Ausrüstung, die mindestens so viel besser ist.", "La fenêtre n'apparaît que pour un équipement au moins autant meilleur.", "La ventana solo aparece para equipo al menos así de mejor.", "Окно появляется только для вещей, лучших хотя бы настолько.", "仅在装备至少提升这么多时显示窗口。" },
    OPT_LO_FULL = { "Window when bags are full", "Fenster bei voller Tasche", "Fenêtre quand les sacs sont pleins", "Ventana con las bolsas llenas", "Окно при полных сумках", "背包满时的窗口" },
    OPT_LO_FULL_TIP = { "Looting with full bags: the cheapest item in your bags, to swap for the loot, delete, skip or ignore.", "Looten bei voller Tasche: der billigste Gegenstand in deinen Taschen, zum Austauschen gegen den Loot, Löschen, Weiterblättern oder Ignorieren.", "Butin avec sacs pleins : l'objet le moins cher de vos sacs, à échanger, supprimer, passer ou ignorer.", "Botín con bolsas llenas: el objeto más barato, para cambiarlo, borrarlo, pasar o ignorar.", "Добыча при полных сумках: самый дешёвый предмет — обменять, удалить, пропустить или игнорировать.", "背包满时拾取：显示背包中最便宜的物品，可交换、删除、跳过或忽略。" },
    OPT_LO_SPEC = { "Rate for", "Bewerten für", "Évaluer pour", "Valorar para", "Оценивать для", "评分依据" },
    OPT_LO_SPEC_TIP = { "Automatic: the talent tree with the most points. The extra profiles (like Shockadin or Battle Mage) are picked here.", "Automatisch: der Talentbaum mit den meisten Punkten. Die Zusatzprofile (etwa Shockadin oder Kampfmagier) wählst du hier.", "Automatique : l'arbre avec le plus de points. Les profils supplémentaires se choisissent ici.", "Automático: el árbol con más puntos. Los perfiles adicionales se eligen aquí.", "Автоматически: ветка с наибольшим числом очков. Дополнительные профили выбираются здесь.", "自动：点数最多的天赋树。额外配置在此选择。" },
    LO_SPEC_AUTO = { "Automatic", "Automatisch", "Automatique", "Automático", "Автоматически", "自动" },
    LO_WEIGHTS_TIP = { "How much one point of each stat is worth for your class and the profile above. The defaults are Pawn Forever's (one set for levelling, one for the highest level). Chances (crit, hit, dodge) count per percent.", "Wie viel ein Punkt jedes Werts für deine Klasse und das Profil oben wert ist. Die Standardwerte stammen von Pawn Forever (je ein Satz fürs Leveln und für die Höchststufe). Chancen (Krit, Treffer, Ausweichen) zählen je Prozent.", "Ce que vaut un point de chaque caractéristique pour votre classe et le profil ci-dessus. Valeurs par défaut de Pawn Forever (montée en niveau et niveau maximum). Les chances comptent par pourcent.", "Cuánto vale un punto de cada atributo para tu clase y el perfil de arriba. Valores de Pawn Forever (subida de nivel y nivel máximo). Las probabilidades cuentan por porcentaje.", "Сколько стоит одно очко характеристики для вашего класса и профиля выше. Значения по умолчанию — Pawn Forever (прокачка и максимальный уровень). Шансы — за процент.", "每点属性对你的职业和上方配置的价值。默认值来自 Pawn Forever（升级与满级各一套）。几率类按百分比计。" },
    LO_CAP = { "Cap for %s", "Deckel für %s", "Plafond de %s", "Tope de %s", "Предел для %s", "%s上限" },
    LO_CAP_TIP = { "More than this (from all your gear together) is worth nothing.", "Mehr als das (aus deiner ganzen Ausrüstung zusammen) ist nichts mehr wert.", "Au-delà (tout votre équipement) cela ne vaut plus rien.", "Más que esto (con todo tu equipo) no vale nada.", "Сверх этого (со всего снаряжения) ничего не стоит.", "超过此值（全身装备合计）不再有价值。" },
    LO_IGNORE_RESET = { "%d ignored items are offered again.", "%d ignorierte Gegenstände werden wieder angeboten.", "%d objets ignorés sont de nouveau proposés.", "%d objetos ignorados se vuelven a ofrecer.", "Снова предлагаются игнорируемые предметы: %d.", "已重新提示 %d 个忽略的物品。" },
    LO_IGNORED_UP = { "Ignored better gear", "Ignorierte bessere Ausrüstung", "Meilleur équipement ignoré", "Equipo mejor ignorado", "Игнорируемое лучшее снаряжение", "已忽略的更好装备" },
    LO_IGNORED_UP_TIP = { "Everything you ignored in the window for better loot is offered again.", "Alles, was du im Fenster bei besserem Loot ignoriert hast, wird wieder angeboten.", "Tout ce que vous avez ignoré dans la fenêtre de meilleur butin est de nouveau proposé.", "Todo lo que ignoraste en la ventana de botín mejor se vuelve a ofrecer.", "Всё, что вы игнорировали в окне лучшей добычи, снова будет предлагаться.", "在更好拾取物窗口中忽略的物品会再次被提示。" },
    LO_IGNORED_FULL = { "Items never to delete", "Nie zu löschende Gegenstände", "Objets à ne jamais supprimer", "Objetos que nunca borrar", "Предметы, которые не удалять", "永不删除的物品" },
    LO_IGNORED_FULL_TIP = { "Everything you ignored in the window for full bags is suggested for deleting again.", "Alles, was du im Fenster bei voller Tasche ignoriert hast, wird wieder zum Löschen vorgeschlagen.", "Tout ce que vous avez ignoré dans la fenêtre des sacs pleins est de nouveau proposé à la suppression.", "Todo lo que ignoraste en la ventana de bolsas llenas se vuelve a sugerir para borrar.", "Всё, что вы игнорировали в окне полных сумок, снова будет предлагаться к удалению.", "在背包满窗口中忽略的物品会再次被建议删除。" },
    LO_RESET_TIP = { "Back to the default weights for this class and profile (Pawn Forever's).", "Zurück auf die Standardgewichte für diese Klasse und dieses Profil (von Pawn Forever).", "Retour aux poids par défaut pour cette classe et ce profil (Pawn Forever).", "Volver a los pesos por defecto de esta clase y perfil (Pawn Forever).", "Вернуть веса по умолчанию для класса и профиля (Pawn Forever).", "恢复该职业和配置的默认权重（Pawn Forever）。" },
    LO_SHARE = { "Share weights", "Gewichte teilen", "Partager les poids", "Compartir pesos", "Поделиться весами", "分享权重" },
    LO_SHARE_TIP = { "Export gives one line with the weights and caps of this class and talent tree, to copy. Import takes such a line and applies it to your class and current talent tree.", "Export gibt eine Zeile mit den Gewichten und Deckeln dieser Klasse und dieses Talentbaums zum Kopieren. Import nimmt so eine Zeile und übernimmt sie für deine Klasse und deinen aktuellen Talentbaum.", "Exporter donne une ligne avec les poids et plafonds à copier. Importer applique une telle ligne à votre classe et arbre actuel.", "Exportar da una línea con los pesos y topes para copiar. Importar aplica una línea así a tu clase y árbol actual.", "Экспорт даёт строку с весами и пределами для копирования. Импорт применяет такую строку к вашему классу и текущей ветке.", "导出：生成一行包含该职业和天赋树权重与上限的文本以复制。导入：将这样一行应用到你的职业和当前天赋树。" },
