    WZ_NEWS = { "What's new", "Neuerungen", "Nouveautés", "Novedades", "Что нового", "新功能" },
    WZ_NEWS_TIP = { "Shows the window that appears after an update, with what the newest version brought.", "Zeigt das Fenster, das nach einem Update erscheint, mit dem, was die neueste Version gebracht hat.", "Affiche la fenêtre qui apparaît après une mise à jour, avec les nouveautés de la dernière version.", "Muestra la ventana que aparece tras una actualización, con lo que trajo la última versión.", "Показывает окно, появляющееся после обновления, с новинками последней версии.", "显示更新后出现的窗口，列出最新版本带来的内容。" },
    WZ_NEWS_BTN = { "Show", "Anzeigen", "Afficher", "Mostrar", "Показать", "显示" },
    WZ_REP_TEXT = { "A reputation bar for the faction you watch: attached to the XP bar, below it or free. Bars can be placed freely in the move mode with its grid (/fqp move), and mail offers your other characters as recipients.", "Eine Ruf-Leiste für die beobachtete Fraktion: an der EP-Leiste, darunter oder frei. Leisten lassen sich im Verschieben-Modus mit Raster frei platzieren (/fqp move), und die Post bietet deine anderen Charaktere als Empfänger an.", "Une barre de réputation pour la faction suivie : accrochée à la barre d'XP, en dessous ou libre. Les barres se placent librement en mode déplacement avec grille (/fqp move), et le courrier propose vos autres personnages.", "Una barra de reputación para la facción que sigues: unida a la barra de PE, debajo o libre. Las barras se colocan en el modo mover con cuadrícula (/fqp move) y el correo ofrece tus otros personajes.", "Полоса репутации для отслеживаемой фракции: у полосы опыта, под ней или свободно. Полосы размещаются в режиме перемещения с сеткой (/fqp move), а почта предлагает ваших персонажей.", "追踪阵营的声望条：挂在经验条下、其下方或自由放置。条可在带网格的移动模式中自由摆放（/fqp move），邮件可选择你的其他角色。" },
    WZ_BEASTS = { "Beasts", "Wildtiere", "Bêtes", "Bestias", "Звери", "野兽" },
    WZ_BEASTS_TEXT = { "For hunters: a tameable beast's tooltip shows which pet ability it teaches, whether your pet can learn it, and its attack speed. Open Beast Training once so the addon knows your abilities.", "Für Jäger: Der Tooltip zähmbarer Wildtiere zeigt, welche Begleiter-Fähigkeit sie lehren, ob dein Begleiter sie lernen kann, und ihr Angriffstempo. Öffne einmal die Wildtierausbildung, damit das Addon deine Fähigkeiten kennt.", "Pour les chasseurs : l'infobulle d'une bête indique la technique qu'elle enseigne, si votre familier peut l'apprendre, et sa vitesse d'attaque.", "Para cazadores: la descripción de una bestia muestra qué habilidad enseña, si tu mascota puede aprenderla y su velocidad de ataque.", "Для охотников: подсказка зверя показывает, какую способность он даёт, может ли её выучить ваш питомец, и скорость атаки.", "猎人：可驯服野兽的提示会显示其教授的技能、你的宠物能否学会以及攻击速度。" },
    WZ_LOOTOPT_TEXT = { "The loot optimizer compares gear with what you wear (weights from Pawn Forever, per class and talent tree), offers better loot to put on and helps when your bags are full.", "Der Loot-Optimierer vergleicht Ausrüstung mit deiner getragenen (Gewichte von Pawn Forever, je Klasse und Talentbaum), bietet besseren Loot zum Anziehen an und hilft bei voller Tasche.", "L'optimiseur de butin compare l'équipement au vôtre (poids de Pawn Forever par classe et arbre), propose un meilleur butin et aide quand les sacs sont pleins.", "El optimizador compara el equipo con el tuyo (pesos de Pawn Forever por clase y árbol), ofrece botín mejor y ayuda con las bolsas llenas.", "Оптимизатор сравнивает снаряжение с надетым (веса Pawn Forever по классу и ветке), предлагает лучшее и помогает при полных сумках.", "拾取优化将装备与已穿戴的比较（权重来自 Pawn Forever，按职业和天赋树），提示穿上更好的物品并在背包满时帮忙。" },
    WZ_SPARKLE_TEXT = { "Quest items in the world sparkle again, like the game itself can show them: graphics presets no longer switch that off. Switching it on or off takes effect after restarting the game.", "Quest-Gegenstände in der Welt funkeln wieder, so wie das Spiel es selbst kann: Grafik-Voreinstellungen schalten das nicht mehr ab. Ein- und Ausschalten wirkt erst nach einem Neustart des Spiels.", "Les objets de quête scintillent à nouveau dans le monde : les préréglages graphiques ne le désactivent plus. L'activation ou la désactivation prend effet après un redémarrage du jeu.", "Los objetos de misión vuelven a brillar en el mundo: los preajustes gráficos ya no lo desactivan. Activarlo o desactivarlo surte efecto al reiniciar el juego.", "Предметы заданий в мире снова сияют: графические пресеты больше не отключают это. Включение и отключение — после перезапуска игры.", "世界中的任务物品再次闪光：图形预设不再将其关闭。开关需重启游戏后生效。" },
    WZ_BEASTPET = { "Your pet", "Dein Begleiter", "Votre familier", "Tu mascota", "Ваш питомец", "你的宠物" },
    WZ_BEASTPET_TEXT = { "For hunters: below every ability a beast teaches, the tooltip now says whether your current pet can learn it, or from which pet level.", "Für Jäger: Unter jeder Fähigkeit, die ein Wildtier lehrt, zeigt der Tooltip jetzt, ob dein aktueller Begleiter sie lernen kann oder ab welcher Begleiter-Stufe.", "Pour les chasseurs : sous chaque technique qu'une bête enseigne, l'infobulle indique si votre familier peut l'apprendre, ou à partir de quel niveau.", "Para cazadores: bajo cada habilidad que enseña una bestia, la descripción indica si tu mascota puede aprenderla o desde qué nivel.", "Для охотников: под каждой способностью зверя подсказка показывает, может ли её выучить ваш питомец или с какого уровня.", "猎人：野兽教授的每个技能下方会显示你当前的宠物能否学会，或需要几级。" },
