    OPT_HEIGHT_TIP = { "How tall the panel is. In the classic look its curved ends follow.", "Wie hoch das Panel ist. Im klassischen Look passen sich die geschwungenen Enden an.", "Hauteur du panneau. En style classique, ses extrémités courbes suivent.", "Altura del panel. En el estilo clásico, sus extremos curvos se adaptan.", "Высота панели. В классическом виде изогнутые края подстраиваются.", "面板的高度。经典外观下弧形两端会随之调整。" },
    OPT_FONTSIZE = { "Font size of the elements", "Schriftgröße der Elemente", "Taille de police des éléments", "Tamaño de fuente de los elementos", "Размер шрифта элементов", "元素字体大小" },
