    OPT_NOTICE_TIP = { "How an element asks for attention, for example on new mail.", "Wie ein Element auf sich aufmerksam macht, zum Beispiel bei neuer Post.", "Comment un élément attire l'attention, par exemple pour un nouveau courrier.", "Cómo un elemento llama la atención, por ejemplo con correo nuevo.", "Как элемент привлекает внимание, например при новой почте.", "元素如何提醒你，例如有新邮件时。" },
    NOTICE_PULSE = { "Pulse", "Pulsieren", "Pulsation", "Pulso", "Пульсация", "脉动" },
