    NOTICE_ICON = { "Icon pulses", "Icon pulsiert", "Icône pulsante", "Icono que late", "Пульсирующий значок", "图标脉动" },
    SEC_BUTTONS = { "Action buttons", "Aktionsknöpfe", "Boutons d'action", "Botones de acción", "Кнопки действий", "动作按钮" },
    BTN_TIP = { "How your action buttons show their state: tinted when a spell cannot be used, and the remaining cooldown as a number.", "Wie deine Aktionsknöpfe ihren Zustand zeigen: eingefärbt, wenn eine Fähigkeit gerade nicht geht, und die verbleibende Abklingzeit als Zahl.", "Comment vos boutons d'action montrent leur état : teintés quand un sort est indisponible, et le temps de recharge restant en chiffres.", "Cómo muestran su estado tus botones de acción: teñidos cuando no se puede usar, y el tiempo de reutilización restante como número.", "Как кнопки показывают состояние: подсветка, когда способность недоступна, и оставшееся время восстановления числом.", "动作按钮如何显示状态：技能不可用时变色，并以数字显示剩余冷却。" },
    SEC_BTN_COLORS = { "State colours", "Zustandsfarben", "Couleurs d'état", "Colores de estado", "Цвета состояния", "状态颜色" },
    OPT_BTN_RANGE = { "Tint the icons", "Icons einfärben", "Teinter les icônes", "Teñir los iconos", "Окрашивать значки", "为图标着色" },
    OPT_BTN_RANGE_TIP = { "The whole icon takes the colour while the target is out of range, you lack the resource, or it cannot be used.", "Das ganze Icon nimmt die Farbe an, solange das Ziel außer Reichweite ist, die Ressource fehlt oder die Fähigkeit nicht nutzbar ist.", "L'icône entière prend la couleur tant que la cible est hors de portée, que la ressource manque ou que le sort est inutilisable.", "Todo el icono toma el color mientras el objetivo está fuera de alcance, falta el recurso o no se puede usar.", "Весь значок окрашивается, пока цель вне досягаемости, не хватает ресурса или способность недоступна.", "目标超出范围、资源不足或技能不可用时，整个图标会变色。" },
    BTN_COL_RANGE = { "Out of range", "Außer Reichweite", "Hors de portée", "Fuera de alcance", "Вне досягаемости", "超出范围" },
    BTN_COL_MANA = { "Not enough mana, rage or energy", "Nicht genug Mana, Wut oder Energie", "Pas assez de mana, rage ou énergie", "Sin maná, ira o energía suficiente", "Не хватает маны, ярости или энергии", "法力、怒气或能量不足" },
    BTN_COL_UNUSABLE = { "Not usable", "Nicht nutzbar", "Inutilisable", "No utilizable", "Недоступно", "不可用" },
    SEC_BTN_CD = { "Cooldown numbers", "Abklingzeit-Ziffern", "Chiffres de recharge", "Números de reutilización", "Цифры восстановления", "冷却数字" },
    OPT_BTN_CD = { "Show the remaining cooldown", "Verbleibende Abklingzeit anzeigen", "Afficher le temps de recharge restant", "Mostrar el tiempo de reutilización restante", "Показывать оставшееся время", "显示剩余冷却" },
    OPT_BTN_CD_TIP = { "A number in the middle of the button; the game's own numbers are hidden while this is on.", "Eine Zahl in der Mitte des Knopfs; die spieleigenen Zahlen sind dann ausgeblendet.", "Un chiffre au centre du bouton ; ceux du jeu sont alors masqués.", "Un número en el centro del botón; los del juego se ocultan.", "Число в центре кнопки; цифры игры при этом скрыты.", "按钮中央显示数字；游戏自带的数字会隐藏。" },
    OPT_BTN_OUTLINE = { "Outline", "Kontur", "Contour", "Contorno", "Обводка", "描边" },
    OUTLINE_NORMAL = { "Normal", "Normal", "Normal", "Normal", "Обычная", "普通" },
    OUTLINE_THICK = { "Thick", "Dick", "Épais", "Grueso", "Толстая", "粗" },
    OPT_BTN_SHADOW = { "Shadow", "Schatten", "Ombre", "Sombra", "Тень", "阴影" },
    OPT_BTN_MIN = { "Shortest cooldown with a number", "Kürzeste Abklingzeit mit Zahl", "Recharge minimale chiffrée", "Reutilización mínima con número", "Минимальное время с числом", "显示数字的最短冷却" },
    OPT_BTN_MIN_TIP = { "Shorter cooldowns (like the global cooldown) get no number.", "Kürzere Abklingzeiten (etwa die globale) bekommen keine Zahl.", "Les recharges plus courtes (comme la globale) n'ont pas de chiffre.", "Las más cortas (como la global) no muestran número.", "Более короткие (например, общее) — без числа.", "更短的冷却（如公共冷却）不显示数字。" },
    OPT_BTN_SHORT = { "Short from", "Kurz ab", "Court à partir de", "Corto desde", "Короткое от", "短冷却阈值" },
    OPT_BTN_SHORT_TIP = { "Below this the number takes the colour for short cooldowns.", "Darunter nimmt die Zahl die Farbe für kurze Abklingzeiten an.", "En dessous, le chiffre prend la couleur des recharges courtes.", "Por debajo, el número toma el color de las cortas.", "Ниже этого число окрашивается как короткое.", "低于此值时数字使用短冷却颜色。" },
    OPT_BTN_DECIMALS = { "Tenths for short cooldowns", "Zehntel bei kurzen Abklingzeiten", "Dixièmes pour les recharges courtes", "Décimas en las cortas", "Десятые для коротких", "短冷却显示小数" },
    BTN_COL_LONG = { "Colour: a minute or more", "Farbe: ab einer Minute", "Couleur : une minute ou plus", "Color: un minuto o más", "Цвет: минута и больше", "颜色：一分钟以上" },
    BTN_COL_MID = { "Colour: seconds", "Farbe: Sekunden", "Couleur : secondes", "Color: segundos", "Цвет: секунды", "颜色：秒" },
    BTN_COL_SHORT = { "Colour: short", "Farbe: kurz", "Couleur : court", "Color: corto", "Цвет: коротко", "颜色：短" },
    WZ_BUTTONS_TEXT = { "Action buttons show their state: tinted when the target is out of range, you lack mana or the spell cannot be used, and the remaining cooldown as a number. Colours, font size, outline and shadow can be set on the Action buttons page.", "Aktionsknöpfe zeigen ihren Zustand: eingefärbt bei Ziel außer Reichweite, fehlendem Mana oder nicht nutzbarer Fähigkeit, dazu die verbleibende Abklingzeit als Zahl. Farben, Schriftgröße, Kontur und Schatten stellst du auf der Seite Aktionsknöpfe ein.", "Les boutons d'action montrent leur état : teintés hors de portée, sans mana ou inutilisables, et le temps de recharge en chiffres. Couleurs, taille, contour et ombre sur la page Boutons d'action.", "Los botones de acción muestran su estado: teñidos fuera de alcance, sin maná o inutilizables, y la reutilización como número. Colores, tamaño, contorno y sombra en la página Botones de acción.", "Кнопки показывают состояние: подсветка вне досягаемости, без маны или недоступно, и время восстановления числом. Цвета, размер, обводка и тень — на странице «Кнопки действий».", "动作按钮会显示状态：超出范围、法力不足或不可用时变色，并以数字显示剩余冷却。颜色、字号、描边和阴影可在动作按钮页面设置。" },
    WZ_PANELLOOK = { "Panel size", "Panel-Größe", "Taille du panneau", "Tamaño del panel", "Размер панели", "面板尺寸" },
    WZ_PANELLOOK_TEXT = { "The panel's height and the font size of its elements can now be set, and how an element asks for attention (new mail): pulse, glow, blink or a pulsing icon.", "Höhe des Panels und Schriftgröße der Elemente lassen sich jetzt einstellen, ebenso wie ein Element auf sich aufmerksam macht (neue Post): pulsieren, leuchten, blinken oder pulsierendes Icon.", "La hauteur du panneau et la taille de police sont réglables, ainsi que l'effet d'alerte (nouveau courrier).", "La altura del panel y el tamaño de fuente se pueden ajustar, igual que el efecto de aviso (correo nuevo).", "Теперь можно задать высоту панели, размер шрифта и эффект уведомления (новая почта).", "现在可以设置面板高度、元素字号以及提示效果（新邮件）。" },
    BTN_PREV_NORMAL = { "Ready", "Bereit", "Prêt", "Listo", "Готово", "就绪" },
    BTN_PREV_MANA = { "No mana", "Kein Mana", "Pas de mana", "Sin maná", "Нет маны", "法力不足" },
    BTN_PREV_LONG = { "Cooldown: minutes", "Abklingzeit: Minuten", "Recharge : minutes", "Reutilización: minutos", "Восст.: минуты", "冷却：分钟" },
    BTN_PREV_MID = { "Cooldown: seconds", "Abklingzeit: Sekunden", "Recharge : secondes", "Reutilización: segundos", "Восст.: секунды", "冷却：秒" },
    BTN_PREV_SHORT = { "Cooldown: short", "Abklingzeit: kurz", "Recharge : courte", "Reutilización: corta", "Восст.: коротко", "冷却：短" },
    SEC_CASTBAR = { "Cast bars", "Zauberleisten", "Barres d'incantation", "Barras de lanzamiento", "Полосы заклинаний", "施法条" },
    CB_TIP = { "The cast bars below the target and focus frames (not the ones on nameplates): as the game shows them, hidden, or placed freely in the move mode.", "Die Zauberleisten unter dem Ziel- und Fokusfenster (nicht die an den Namensplaketten): wie im Spiel, ausgeblendet oder frei im Verschieben-Modus platziert.", "Les barres d'incantation sous les cadres de cible et de focalisation (pas celles des barres de nom) : comme le jeu, masquées ou placées librement en mode déplacement.", "Las barras de lanzamiento bajo los marcos de objetivo y foco (no las de las placas de nombre): como en el juego, ocultas o colocadas libremente en el modo mover.", "Полосы заклинаний под рамками цели и фокуса (не на индикаторах): как в игре, скрыты или свободно в режиме перемещения.", "目标和焦点框体下的施法条（不是姓名板上的）：保持默认、隐藏或在移动模式中自由放置。" },
    CB_TARGET = { "Target's cast bar", "Zauberleiste des Ziels", "Barre de la cible", "Barra del objetivo", "Полоса цели", "目标施法条" },
    CB_FOCUS = { "Focus's cast bar", "Zauberleiste des Fokus", "Barre de la focalisation", "Barra del foco", "Полоса фокуса", "焦点施法条" },
    OPT_CB_MODE = { "Show", "Anzeige", "Affichage", "Mostrar", "Показ", "显示" },
    CB_DEFAULT = { "As in the game", "Wie im Spiel", "Comme le jeu", "Como en el juego", "Как в игре", "默认" },
    CB_HIDE = { "Hidden", "Ausgeblendet", "Masquée", "Oculta", "Скрыта", "隐藏" },
    OPT_CB_SCALE = { "Size", "Größe", "Taille", "Tamaño", "Размер", "大小" },
    WZ_SOUNDS = { "Warning sounds", "Warntöne", "Sons d'alerte", "Sonidos de aviso", "Звуки предупреждений", "警告音" },
    WZ_SOUNDS_TEXT = { "Every kind of warning (class buffs, expiring buffs, food, flask, weapon buff, ammo) can now have its own sound; it plays when that warning appears. All sounds are in the options under Warnings.", "Jede Art von Warnung (Klassenbuffs, auslaufende Buffs, Essen, Fläschchen, Waffenbuff, Munition) kann jetzt einen eigenen Ton haben; er erklingt, wenn die Warnung erscheint. Alle Töne findest du in den Optionen unter Warnungen.", "Chaque type d'avertissement (buffs de classe, buffs expirants, nourriture, flacon, buff d'arme, munitions) peut avoir son propre son, joué à son apparition. Tous les sons sont dans les options sous Avertissements.", "Cada tipo de aviso (beneficios de clase, beneficios por expirar, comida, frasco, beneficio de arma, munición) puede tener su propio sonido, que suena al aparecer. Todos los sonidos están en las opciones, en Avisos.", "Для каждого вида предупреждений (классовые баффы, истекающие баффы, еда, настой, бафф оружия, боеприпасы) теперь можно выбрать свой звук — он звучит при появлении. Все звуки — в настройках, раздел «Предупреждения».", "每种警告（职业增益、即将结束的增益、食物、合剂、武器增益、弹药）现在都可以有自己的声音，警告出现时播放。所有声音都在选项的警告中。" },
    WZ_RING = { "XP and reputation around the minimap", "EP und Ruf um die Minimap", "XP et réputation autour de la minicarte", "PE y reputación alrededor del minimapa", "Опыт и репутация вокруг миникарты", "小地图周围的经验和声望" },
    WZ_NEWEL = { "New panel elements", "Neue Panel-Elemente", "Nouveaux éléments du panneau", "Nuevos elementos del panel", "Новые элементы панели", "新的面板元素" },
    WZ_RING_TEXT = { "The XP bar and the reputation bar can run as rings around the minimap, in the bar's look with its border, tick marks and tooltip; finished quests show in the look chosen for the bar. The reputation ring goes outside the XP ring, at 0 px they share one border. Width and distance for each.", "EP- und Ruf-Leiste können als Ringe um die Minimap laufen, im Look der Leiste mit Rand, Teilstrichen und Tooltip; fertige Quests erscheinen in der Darstellung, die für die Leiste gewählt ist. Der Ruf-Ring liegt außen um den EP-Ring, bei 0 px teilen sie sich einen Rand. Breite und Abstand je Ring.", "Les barres d'XP et de réputation peuvent entourer la minicarte en anneaux, au style de la barre avec bordure, graduations et infobulle ; les quêtes terminées suivent le style choisi pour la barre. L'anneau de réputation entoure celui d'XP, à 0 px ils partagent une bordure. Largeur et distance pour chacun.", "Las barras de PE y reputación pueden rodear el minimapa como anillos, con el aspecto de la barra, borde, marcas y descripción; las misiones terminadas siguen el estilo elegido para la barra. El de reputación va por fuera del de PE, a 0 px comparten un borde. Ancho y distancia para cada uno.", "Полосы опыта и репутации могут идти кольцами вокруг миникарты — в стиле полосы, с рамкой, делениями и подсказкой; выполненные задания показываются в выбранном для полосы виде. Кольцо репутации снаружи, при 0 px у них общая рамка. Ширина и отступ у каждого свои.", "经验条和声望条可以作为圆环围绕小地图，保持经验条的边框、刻度和提示；已完成任务按经验条所选样式显示。声望环在经验环外侧，0 px 时共用一条边框。各自可调宽度和距离。" },
    WZ_MMSHAPE_TEXT = { "The minimap can be square with a border in the panel's classic or modern look. Minimap buttons (also other addons') line up along the square, the XP and reputation rings become square frames.", "Die Minimap kann quadratisch sein, mit einem Rahmen im klassischen oder modernen Look des Panels. Minimap-Buttons (auch die anderer Addons) reihen sich am Quadrat auf, EP- und Ruf-Ring werden zu quadratischen Rahmen.", "La minicarte peut être carrée avec un cadre au style classique ou moderne du panneau. Les boutons (aussi ceux des autres addons) s'alignent sur le carré, les anneaux d'XP et de réputation deviennent des cadres carrés.", "El minimapa puede ser cuadrado con un marco del aspecto clásico o moderno del panel. Los botones (también de otros addons) se alinean en el cuadrado, los anillos de PE y reputación pasan a ser marcos cuadrados.", "Миникарта может быть квадратной с рамкой в классическом или современном стиле панели. Кнопки (и других аддонов) выстраиваются по квадрату, кольца опыта и репутации становятся квадратными рамками.", "小地图可以是方形，带面板经典或现代风格边框。小地图按钮（包括其他插件的）沿方形排列，经验环和声望环变为方形边框。" },
    WZ_MMEL_TEXT = { "The game's elements at the minimap can be hidden one by one.", "Die Elemente des Spiels an der Minimap lassen sich einzeln ausblenden.", "Les éléments du jeu sur la minicarte peuvent être masqués un par un.", "Los elementos del juego en el minimapa pueden ocultarse uno a uno.", "Элементы игры у миникарты можно скрыть по отдельности.", "小地图上的游戏元素可逐个隐藏。" },
    WZ_NEWEL_TEXT = { "Tracking: what the minimap tracks (short name or just the icon), a click switches it. WIM whispers (with WIM 3 installed): new messages at a glance, clicks as on WIM's own button, which can then be hidden. Mail and WIM can show just their icon while there is nothing new.", "Aufspüren: was die Minimap aufspürt (kurzer Name oder nur das Symbol), ein Klick wechselt es. WIM-Nachrichten (wenn WIM 3 installiert ist): neue Nachrichten auf einen Blick, Klicks wie bei WIMs eigenem Button, der sich dann ausblenden lässt. Post und WIM können nur ihr Symbol zeigen, solange nichts Neues da ist.", "Pistage : ce que la minicarte piste (nom court ou icône seule), un clic le change. Messages WIM (avec WIM 3) : nouveaux messages d'un coup d'œil, clics comme sur le bouton de WIM, qui peut alors être masqué. Courrier et WIM peuvent n'afficher que leur icône sans nouveauté.", "Rastreo: lo que rastrea el minimapa (nombre corto o solo icono), un clic lo cambia. Mensajes de WIM (con WIM 3): mensajes nuevos de un vistazo, clics como en el botón de WIM, que puede ocultarse. Correo y WIM pueden mostrar solo su icono si no hay nada nuevo.", "Отслеживание: что отслеживает миникарта (коротко или только значок), клик переключает. Сообщения WIM (с WIM 3): новые сообщения сразу видны, клики как у кнопки WIM, которую можно скрыть. Почта и WIM могут показывать только значок, пока нет нового.", "追踪：小地图追踪的内容（简称或仅图标），点击切换。WIM 消息（需 WIM 3）：一眼看到新消息，点击同 WIM 按钮，该按钮可隐藏。邮件和 WIM 无新内容时可只显示图标。" },
    WZ_MORE = { "More that is new", "Weitere Neuerungen", "Autres nouveautés", "Más novedades", "Другие новшества", "其他新内容" },
    WZ_MORE_TEXT = { "The options window has tabs: XP and reputation bar share a page, Elements, Loot optimizer and Warnings are split into tabs, the Minimap page is new. The XP tooltip shows each finished quest's share of the level in percent. Characters: Forever's client no longer reports the realm, so the addon finds it another way and merges the duplicates.", "Das Optionsfenster hat Tabs: EP- und Ruf-Leiste teilen sich eine Seite, Elemente, Loot-Optimierer und Warnungen sind in Tabs geteilt, die Minimap-Seite ist neu. Der EP-Tooltip zeigt bei fertigen Quests den Anteil an der Stufe in Prozent. Charaktere: Forevers Client meldet den Realm nicht mehr, das Addon findet ihn anders und führt doppelte Einträge zusammen.", "La fenêtre d'options a des onglets : barres d'XP et de réputation sur une page, Éléments, Optimiseur de butin et Avertissements en onglets, nouvelle page Minicarte. L'infobulle d'XP montre la part du niveau de chaque quête terminée en pourcentage. Personnages : le client ne donne plus le royaume, l'addon le trouve autrement et fusionne les doublons.", "La ventana de opciones tiene pestañas: barras de PE y reputación en una página, Elementos, Optimizador de botín y Avisos en pestañas, nueva página Minimapa. La descripción de PE muestra el porcentaje del nivel de cada misión terminada. Personajes: el cliente ya no da el reino, el addon lo encuentra de otra forma y une los duplicados.", "В окне настроек есть вкладки: полосы опыта и репутации на одной странице, Элементы, Оптимизатор добычи и Предупреждения разделены на вкладки, новая страница «Миникарта». Подсказка опыта показывает долю уровня каждого выполненного задания в процентах. Персонажи: клиент больше не сообщает игровой мир, аддон находит его иначе и объединяет дубликаты.", "选项窗口新增标签页：经验条和声望条共用一页，元素、拾取优化器和警告分为标签页，新增小地图页面。经验提示显示每个已完成任务占本级的百分比。角色：客户端不再报告服务器，插件改用其他方式识别并合并重复项。" },
    WZ_XP_WHERE = { "XP bar", "EP-Leiste", "Barre d'XP", "Barra de PE", "Полоса опыта", "经验条" },
    WZ_XP_RINGW = { "XP ring: width", "EP-Ring: Breite", "Anneau d'XP : largeur", "Anillo de PE: ancho", "Кольцо опыта: ширина", "经验环：宽度" },
    WZ_XP_RINGG = { "XP ring: distance", "EP-Ring: Abstand", "Anneau d'XP : distance", "Anillo de PE: distancia", "Кольцо опыта: отступ", "经验环：距离" },
    WZ_REP_WHERE = { "Reputation bar", "Ruf-Leiste", "Barre de réputation", "Barra de reputación", "Полоса репутации", "声望条" },
    WZ_REP_RINGW = { "Reputation ring: width", "Ruf-Ring: Breite", "Anneau de réputation : largeur", "Anillo de reputación: ancho", "Кольцо репутации: ширина", "声望环：宽度" },
    WZ_REP_RINGG = { "Reputation ring: distance", "Ruf-Ring: Abstand", "Anneau de réputation : distance", "Anillo de reputación: distancia", "Кольцо репутации: отступ", "声望环：距离" },
    WZ_PET_TEXT = { "Hunters: your pet's level and XP as a bar – beside the XP bar (both share its width), hanging from it, around the minimap (in the XP ring's place), free with your own size, or below the pet's portrait. Beside or hanging, the reputation bar moves below.", "Jäger: Stufe und EP deines Begleiters als Leiste – neben der EP-Leiste (beide teilen sich ihre Breite), an ihr hängend, um die Minimap (statt des EP-Rings), frei mit eigener Größe oder unter dem Begleiter-Porträt. Neben oder hängend rückt die Ruf-Leiste darunter.", "Chasseurs : niveau et XP du familier en barre – à côté de la barre d'XP (largeur partagée), suspendue à elle, autour de la minicarte (à la place de l'anneau d'XP), libre avec votre taille, ou sous le portrait du familier. À côté ou suspendue, la barre de réputation passe en dessous.", "Cazadores: nivel y PE de tu mascota como barra – junto a la barra de PE (comparten ancho), colgando de ella, alrededor del minimapa (en lugar del anillo de PE), libre con tu tamaño o bajo el retrato de la mascota. Junto o colgando, la de reputación va debajo.", "Охотники: уровень и опыт питомца полосой — рядом с полосой опыта (общая ширина), под ней, вокруг миникарты (вместо кольца опыта), свободно со своим размером или под портретом питомца. Рядом или под ней полоса репутации уходит ниже.", "猎人：以条形显示宠物等级和经验——在经验条旁（共享宽度）、悬挂在其下、围绕小地图（替代经验环）、自由放置并自定尺寸，或在宠物头像下方。在旁或悬挂时声望条移到下方。" },
    WZ_PET_TICKS = { "Tick marks every", "Teilstriche alle", "Graduations tous les", "Marcas cada", "Деления каждые", "刻度间隔" },
    WZ_PETSIZE = { "Pet bar: size", "Begleiter-Leiste: Größe", "Barre du familier : taille", "Barra de mascota: tamaño", "Полоса питомца: размер", "宠物条：尺寸" },
    WZ_PETSIZE_TEXT = { "Beside the XP bar: which side and how much of the width. Hanging from it: its width. Free: width and height (placed in the move mode).", "Neben der EP-Leiste: welche Seite und wie viel der Breite. An ihr hängend: die Breite. Frei: Breite und Höhe (platziert im Verschieben-Modus).", "À côté de la barre d'XP : quel côté et quelle part de largeur. Suspendue : sa largeur. Libre : largeur et hauteur (placée en mode déplacement).", "Junto a la barra de PE: qué lado y qué parte del ancho. Colgando: su ancho. Libre: ancho y altura (colocada en el modo mover).", "Рядом с полосой опыта: сторона и доля ширины. Под ней: ширина. Свободно: ширина и высота (в режиме перемещения).", "经验条旁：哪一侧及宽度占比。悬挂：宽度。自由：宽度和高度（在移动模式中放置）。" },
    WZ_PET_ATTACHW = { "Hanging: width", "Hängend: Breite", "Suspendue : largeur", "Colgando: ancho", "Под полосой: ширина", "悬挂：宽度" },
    WZ_PET_FREEW = { "Free: width", "Frei: Breite", "Libre : largeur", "Libre: ancho", "Свободно: ширина", "自由：宽度" },
    WZ_PET_FREEH = { "Free: height", "Frei: Höhe", "Libre : hauteur", "Libre: altura", "Свободно: высота", "自由：高度" },
    WZ_LOOTCLASS_TEXT = { "The loot optimizer no longer offers items only other classes may wear (“Classes: Rogue” in the tooltip), like a rogues' mask.", "Der Loot-Optimierer bietet keine Gegenstände mehr an, die nur andere Klassen tragen dürfen („Klassen: Schurke“ im Tooltip), etwa eine Schurken-Maske.", "L'optimiseur de butin ne propose plus d'objets réservés à d'autres classes (« Classes : Voleur » dans l'infobulle), comme un masque de voleur.", "El optimizador de botín ya no ofrece objetos solo para otras clases («Clases: Pícaro» en la descripción), como una máscara de pícaro.", "Оптимизатор добычи больше не предлагает предметы только для других классов («Классы: Разбойник» в подсказке), например маску разбойника.", "拾取优化器不再推荐仅限其他职业的物品（提示中“职业：潜行者”），例如潜行者面具。" },
    WZ_RADAR_TEXT = { "Enemy players nearby, like Spy: a sound for each new one, another sound and a red warning in the middle of the screen for one going into stealth. The panel element shows the count and opens a list (class icon, name, level). Try it in the options with the button there.", "Gegnerische Spieler in der Nähe, wie bei Spy: ein Ton für jeden neuen, ein anderer Ton und eine rote Warnung in der Bildschirmmitte bei Verstohlenheit. Das Panel-Element zeigt die Anzahl und öffnet eine Liste (Klassen-Symbol, Name, Stufe). In den Optionen kannst du es per Button ausprobieren.", "Joueurs ennemis proches, comme Spy : un son pour chaque nouveau, un autre son et une alerte rouge au centre pour le camouflage. L'élément du panneau affiche le nombre et ouvre une liste (icône de classe, nom, niveau). Essayez-le dans les options avec le bouton.", "Jugadores enemigos cerca, como Spy: un sonido por cada nuevo, otro sonido y un aviso rojo en el centro para el sigilo. El elemento del panel muestra el número y abre una lista (icono de clase, nombre, nivel). Pruébalo en las opciones con el botón.", "Вражеские игроки рядом, как в Spy: звук на каждого нового, другой звук и красное предупреждение в центре при незаметности. Элемент панели показывает число и открывает список (значок класса, имя, уровень). Попробуйте кнопкой в настройках.", "附近的敌方玩家，类似 Spy：每个新敌人一种提示音，潜行时另一种提示音并在屏幕中央显示红色警告。面板元素显示数量并打开列表（职业图标、名字、等级）。可在选项中用按钮试用。" },
    WZ_RADAR_ITEM = { "Element on the panel", "Element im Panel", "Élément sur le panneau", "Elemento en el panel", "Элемент на панели", "面板元素" },
    WZ_RADARLIST = { "Enemy radar: list", "Feindradar: Liste", "Radar ennemi : liste", "Radar de enemigos: lista", "Радар врагов: список", "敌人雷达：列表" },
    WZ_RADARLIST_TEXT = { "The list below the element: whether it opens by itself, how many rows at most, how long an enemy stays in it, and whether the element shows text without enemies.", "Die Liste unter dem Element: ob sie sich von selbst öffnet, wie viele Zeilen höchstens, wie lange ein Gegner darin bleibt und ob das Element ohne Gegner Text zeigt.", "La liste sous l'élément : ouverture automatique, nombre de lignes maximal, durée de présence d'un ennemi, et texte de l'élément sans ennemi.", "La lista bajo el elemento: si se abre sola, cuántas filas como máximo, cuánto tiempo queda un enemigo y si el elemento muestra texto sin enemigos.", "Список под элементом: открывается ли сам, сколько строк максимум, как долго враг в нём остаётся и показывает ли элемент текст без врагов.", "元素下方的列表：是否自动打开、最多行数、敌人保留时长，以及无敌人时元素是否显示文字。" },
    WZ_CASTBAR_TEXT = { "The cast bar below the target frame can now be hidden or placed anywhere (move mode) and scaled, which the standard interface cannot do. The same goes for the focus frame's bar, where the game has one.", "Die Zauberleiste unter dem Zielfenster lässt sich jetzt ausblenden oder frei platzieren (Verschieben-Modus) und skalieren, was das Standard-UI nicht kann. Dasselbe gilt für die Leiste des Fokusfensters, falls das Spiel eines hat.", "La barre d'incantation sous le cadre de cible peut être masquée ou placée librement (mode déplacement) et redimensionnée. De même pour la focalisation, si le jeu en a une.", "La barra de lanzamiento bajo el marco de objetivo se puede ocultar o colocar libremente (modo mover) y escalar. Igual para el foco, si el juego lo tiene.", "Полосу заклинаний под рамкой цели теперь можно скрыть или разместить свободно (режим перемещения) и масштабировать. То же для фокуса, если он есть.", "目标框体下的施法条现在可以隐藏或自由放置（移动模式）并缩放。焦点施法条同理（如游戏提供）。" },
    SEC_MAIL = { "Mail", "Post", "Courrier", "Correo", "Почта", "邮件" },
    OPT_GP_MAILALTS = { "Pick your characters as recipient", "Eigene Charaktere als Empfänger wählen", "Choisir vos personnages comme destinataire", "Elegir tus personajes como destinatario", "Выбирать своих персонажей получателями", "选择自己的角色作为收件人" },
    MAIL_ALTS = { "Your characters", "Deine Charaktere", "Vos personnages", "Tus personajes", "Ваши персонажи", "你的角色" },
    MAIL_ALTS_TIP = { "An arrow next to the recipient lists your other characters on this realm and faction. A character appears once it has logged in with the addon.", "Ein Pfeil neben dem Empfänger listet deine anderen Charaktere auf diesem Realm und dieser Fraktion. Ein Charakter erscheint, sobald er sich einmal mit dem Addon eingeloggt hat.", "Une flèche à côté du destinataire liste vos autres personnages de ce royaume et de cette faction. Un personnage apparaît dès qu'il s'est connecté une fois avec l'addon.", "Una flecha junto al destinatario muestra tus otros personajes de este reino y facción. Un personaje aparece tras conectarse una vez con el addon.", "Стрелка рядом с получателем показывает других ваших персонажей этого мира и фракции. Персонаж появится после первого входа с аддоном.", "收件人旁的箭头会列出你在本服务器和阵营的其他角色。角色在安装插件后登录一次即会出现。" },
    MAIL_NO_ALTS = { "None yet: log in with them once.", "Noch keine: einmal mit ihnen einloggen.", "Aucun pour l'instant : connectez-vous une fois avec eux.", "Ninguno aún: conéctate una vez con ellos.", "Пока нет: войдите ими один раз.", "暂无：请用它们登录一次。" },
    GP_SELL_BLOCKED = { "The game didn't let the grey items be sold automatically. Use the merchant's junk button.", "Das Spiel hat das automatische Verkaufen der grauen Gegenstände nicht zugelassen. Nutze den Plunder-Knopf beim Händler.", "Le jeu n'a pas permis la vente automatique des objets gris. Utilisez le bouton de camelote du marchand.", "El juego no permitió vender los objetos grises automáticamente. Usa el botón de chatarra del mercader.", "Игра не позволила продать серые предметы автоматически. Используйте кнопку продажи хлама у торговца.", "游戏未允许自动出售灰色物品。请使用商人的出售垃圾按钮。" },
    GP_REPAIRED = { "Repaired for %s.", "Für %s repariert.", "Réparé pour %s.", "Reparado por %s.", "Ремонт: %s.", "修理花费 %s。" },
    GP_REPAIRED_GUILD = { "Repaired for %s (guild).", "Für %s repariert (Gilde).", "Réparé pour %s (guilde).", "Reparado por %s (hermandad).", "Ремонт: %s (гильдия).", "修理花费 %s（公会）。" },
    GP_NO_MONEY = { "Not enough money to repair (%s).", "Nicht genug Geld zum Reparieren (%s).", "Pas assez d'argent pour réparer (%s).", "No hay dinero suficiente para reparar (%s).", "Не хватает денег на ремонт (%s).", "金钱不足以修理（%s）。" },
    SEC_NAMEPLATES = { "Quest markers", "Questmarker", "Marqueurs de quête", "Marcadores de misión", "Метки заданий", "任务标记" },
    OPT_NP = { "Quest markers on nameplates", "Questmarker an Namensplaketten", "Marqueurs de quête sur les barres de nom", "Marcadores de misión en placas de nombre", "Метки заданий на индикаторах", "姓名板任务标记" },
    OPT_NP_TIP = { "Units your quests still need get a quest icon. Needs nameplates switched on.", "Einheiten, die deine Quests noch brauchen, bekommen ein Quest-Symbol. Namensplaketten müssen eingeschaltet sein.", "Les unités dont vos quêtes ont encore besoin reçoivent une icône. Les barres de nom doivent être activées.", "Las unidades que tus misiones aún necesitan reciben un icono. Requiere placas de nombre activadas.", "Цели, нужные для заданий, получают значок. Индикаторы должны быть включены.", "任务仍需要的单位会显示任务图标。需要开启姓名板。" },
    OPT_NP_POS = { "Marker position", "Position des Markers", "Position du marqueur", "Posición del marcador", "Положение метки", "标记位置" },
    NP_LEFT = { "Left of the name", "Links vom Namen", "À gauche du nom", "A la izquierda del nombre", "Слева от имени", "名字左侧" },
    NP_RIGHT = { "Right of the name", "Rechts vom Namen", "À droite du nom", "A la derecha del nombre", "Справа от имени", "名字右侧" },
    NP_TOP = { "Above the name", "Über dem Namen", "Au-dessus du nom", "Encima del nombre", "Над именем", "名字上方" },
    OPT_NP_PROGRESS = { "Show progress (3/8)", "Fortschritt zeigen (3/8)", "Afficher la progression (3/8)", "Mostrar progreso (3/8)", "Показывать прогресс (3/8)", "显示进度（3/8）" },
    SEC_WARNINGS = { "Warnings", "Warnungen", "Alertes", "Avisos", "Предупреждения", "提醒" },
    OPT_WARNINGS = { "Buff and consumable warnings", "Buff- und Consumable-Warnungen", "Alertes d'améliorations et de consommables", "Avisos de beneficios y consumibles", "Предупреждения о баффах и расходниках", "增益与消耗品提醒" },
    OPT_WARNINGS_TIP = { "Out of combat, below the top of the screen.", "Außerhalb des Kampfes, unter dem oberen Bildschirmrand.", "Hors combat, sous le haut de l'écran.", "Fuera de combate, bajo la parte superior de la pantalla.", "Вне боя, под верхним краем экрана.", "非战斗时，显示在屏幕上方。" },
    OPT_WARN_CLASS = { "Own class buffs missing", "Eigene Klassen-Buffs fehlen", "Améliorations de classe manquantes", "Faltan beneficios de clase", "Нет собственных классовых баффов", "缺少本职业增益" },
    OPT_WARN_FOOD = { "Buff food (Well Fed)", "Buff-Essen (Satt)", "Nourriture (Bien nourri)", "Comida (Bien alimentado)", "Еда (Сытость)", "增益食物（进食充分）" },
    OPT_WARN_FOOD_TIP = { "Warns when you are not Well Fed.", "Warnt, wenn du nicht satt bist.", "Alerte si vous n'êtes pas bien nourri.", "Avisa si no estás bien alimentado.", "Предупреждает, если нет сытости.", "未进食充分时提醒。" },
    OPT_WARN_WEAPON = { "Weapon buffs missing", "Waffenbuffs fehlen", "Améliorations d'arme manquantes", "Faltan mejoras de arma", "Нет усилений оружия", "缺少武器增益" },
    OPT_WARN_WEAPON_TIP = { "Rogues and shamans always; everyone else after a stone or oil ran out.", "Schurken und Schamanen immer; alle anderen, nachdem ein Stein oder Öl abgelaufen ist.", "Voleurs et chamans toujours ; les autres après expiration d'une pierre ou huile.", "Pícaros y chamanes siempre; el resto cuando se acaba una piedra o aceite.", "Разбойники и шаманы всегда; остальные после окончания камня или масла.", "潜行者和萨满始终提醒；其他职业在磨刀石或油失效后提醒。" },
    OPT_WARN_EXPIRING = { "Own buffs about to run out", "Eigene Buffs laufen bald ab", "Améliorations sur le point d'expirer", "Beneficios a punto de acabar", "Баффы скоро закончатся", "自身增益即将结束" },
    OPT_WARN_SOUND_CAT = { "Warning sound", "Warnton", "Son d'alerte", "Sonido de aviso", "Звук предупреждения", "警告音" },
